int C[10][10];

int main()
{
    //freopen("in.txt","r",stdin);
    //freopen("out.txt","w",stdout);
	C[0][0] = 1;
	for(int i = 1;i < 10;i++){
		C[i][0] = C[i][i] = 1;
		for(int j = 1;j < i;j++)
			C[i][j] = C[i-1][j] + C[i-1][j-1];
	}
	int T;
   int a,b;
	scanf("%d",&T);   
	int iCase = 0;
