			tmp += (double)C[b][i]*pow((double)(a-1),(double)(b-i));
		}
		tmp /= 2;
		for(int i = 1;i < b;i++)tmp /= a;
		tmp *= (a+1);
		//printf("%.3lf\n",tmp);
		double ans = (1-pow((double)(a-1)/a,(double)b))*a*(a+1)/2;
		printf("Case #%d: %.3lf\n",iCase,ans);
	}
    return 0;
}

