	int c0,c1;
	c0 = c1 = 0;
	long long ans = 0;
	int i = 31;
	while(i >= 0){
		int end;
		if(n&bit[i])end = 1;
		else end = 0;
		if(end){
			int re = 0;
			int cc0 = c0, cc1 = c1;
			cc0++;
			for(int j = i-1;j >= 0;j--){
				if((c&bit[j]) == 0)
					cc0++;
				else re++;
			}
			for(int j = 0;j <= re;j++){
				if(abs( (j+cc0) - (cc1 + re-j) ) <= k)
					ans += C[re][j];
			}
		}
		if(end == 1 && (c&bit[i]) == 0)break;
		if(end)c1++;
		else c0++;
		i--;
	}
	if(i < 0){
		if(abs(c0-c1) <= k)ans++;
	}
	return ans;
}
