/*
*`suffix array`
*`�����㷨  O(n*logn)`
*`���������鳤��Ϊn,����0~n-1�У�������油һ��0`
*`da(str ,sa,rank,height, n ,   );//ע����n;`
*`���磺`
*`n   = 8;`
* num[]   = { 1, 1, 2, 1, 1, 1, 1, 2, $ }; `ע��num���һλΪ0����������0`
*`rank[]  = { 4, 6, 8, 1, 2, 3, 5, 7, 0 };rank[0~n-1]Ϊ��Чֵ��rank[n]�ض�Ϊ0��Чֵ`
*`sa[]    = { 8, 3, 4, 5, 0, 6, 1, 7, 2 };sa[1~n]Ϊ��Чֵ��sa[0]�ض�Ϊn����Чֵ`
*`height[]= { 0, 0, 3, 2, 3, 1, 2, 0, 1 };height[2~n]Ϊ��Чֵ`
*
*/
const int MAXN=200010;
int t1[MAXN],t2[MAXN],c[MAXN];//`��SA������Ҫ���м����������Ҫ��ֵ`
//`��������ַ�������s�����У���s[0]��s[n-1],����Ϊn,�����ֵС��m,`
//`��s[n-1]�������s[i]������0��r[n-1]=0`
//`���������Ժ�������sa������`
bool cmp(int *r,int a,int b,int l){
	return r[a] == r[b] && r[a+l] == r[b+l];
}
void da(int str[],int sa[],int rank[],int height[],int n,int m){
    n++;
    int i, j, p, *x = t1, *y = t2;
    //`��һ�ֻ����������s�����ֵ�ܴ󣬿ɸ�Ϊ��������`
    for(i = 0;i < m;i++)c[i] = 0;
    for(i = 0;i < n;i++)c[x[i] = str[i]]++;
    for(i = 1;i < m;i++)c[i] += c[i-1];
    for(i = n-1;i >= 0;i--)sa[--c[x[i]]] = i;
    for(j = 1;j <= n; j <<= 1){
        p = 0;
        //`ֱ������sa��������ڶ��ؼ���`
        for(i = n-j; i < n; i++)y[p++] = i;//`�����j�����ڶ��ؼ���Ϊ�յ���С`
        for(i = 0; i < n; i++)if(sa[i] >= j)y[p++] = sa[i] - j;
        //`��������y����ľ��ǰ��յڶ��ؼ�������Ľ��`
        //`���������һ�ؼ���`
        for(i = 0; i < m; i++)c[i] = 0;
        for(i = 0; i < n; i++)c[x[y[i]]]++;
        for(i = 1; i < m;i++)c[i] += c[i-1];
        for(i = n-1; i >= 0;i--)sa[--c[x[y[i]]]] = y[i];
        //`����sa��x��������µ�x����`
        swap(x,y);
        p = 1; x[sa[0]] = 0;
        for(i = 1;i < n;i++)
            x[sa[i]] = cmp(y,sa[i-1],sa[i],j)?p-1:p++;
        if(p >= n)break;
        m = p;//`�´λ�����������ֵ`
    }
    int k = 0;
    n--;
	for(i = 0;i <= n;i++)rank[sa[i]] = i;
    for(i = 0;i < n;i++){
        if(k)k--;
        j = sa[rank[i]-1];
        while(str[i+k] == str[j+k])k++;
        height[rank[i]] = k;
    }
}
int rank[MAXN],height[MAXN];
int RMQ[MAXN];
int mm[MAXN];
int best[20][MAXN];
void initRMQ(int n){
    mm[0]=-1;
    for(int i=1;i<=n;i++)
        mm[i]=((i&(i-1))==0)?mm[i-1]+1:mm[i-1];
    for(int i=1;i<=n;i++)best[0][i]=i;
    for(int i=1;i<=mm[n];i++)
        for(int j=1;j+(1<<i)-1<=n;j++){
            int a=best[i-1][j];
            int b=best[i-1][j+(1<<(i-1))];
            if(RMQ[a]<RMQ[b])best[i][j]=a;
            else best[i][j]=b;
        }
}
int askRMQ(int a,int b){
    int t;
    t=mm[b-a+1];
    b-=(1<<t)-1;
    a=best[t][a];b=best[t][b];
    return RMQ[a]<RMQ[b]?a:b;
}
int lcp(int a,int b){
    a=rank[a];b=rank[b];
    if(a>b)swap(a,b);
    return height[askRMQ(a+1,b)];
}
char stra[MAXN],strb[MAXN];
int r[MAXN];
int sa[MAXN];
int len1,len2;
int LCP(int i,int j){
	return lcp(i,len1+1+j);
}
int k;
bool check(int id){
	if(id + len2 > len1)return false;
	int tt = k;
	int i = id;
	int j = 0;
	while(1){
		int tmp = LCP(i,j);
		i += tmp;
		j += tmp;
		if(j >= len2)return true;
		if(tt == 0)break;
		i++;
		j++;
		tt--;
		if(j >= len2)return true;
	}
	return false;
}

int main()
{
    //freopen("in.txt","r",stdin);
    //freopen("out.txt","w",stdout);
	while(scanf("%s%s%d",stra,strb,&k) == 3){
		len1 = strlen(stra);
		len2 = strlen(strb);
		if(len1 < len2){
			printf("0\n");
			continue;
		}
		if(k >= len2){
			printf("%d\n",len1-len2+1);
			continue;
		}
		int n = len1+len2+1;
		for(int i = 0;i < len1;i++)r[i] = stra[i];
		for(int i = 0;i < len2;i++)r[len1+1+i] = strb[i];
		r[len1] = 1;
		r[n] = 0;
		da(r,sa,rank,height,n,128);
		for(int i = 1;i <= n;i++)RMQ[i] = height[i];
		initRMQ(n);
		int ans = 0;
		for(int i = 0;i < len1;i++)
			if(check(i))
				ans++;
		printf("%d\n",ans);
	}
    return 0;
}

﻿#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <functional>
#include <array>
using namespace std;
const int dim = 2;
using vec = array<double, dim>;
/*
* grad: 计算梯度的函数
* pos: 搜索的起始点
* lr: 学习率（移动的步长）
* decay: 学习率的衰减指数
* exit: 当学习率小于exit时算法结束
* 注意该算法求出的是 函数的极**小**值点
*/
vec Adam(function<vec(vec)> grad, vec pos, double lr, double decay, double exit,
	const double beta1 = 0.9, const double beta2 = 0.9) {
	double pw1 = 1, pw2 = 1;
	vec m = {}, v = {};
	for (int t = 1; lr >= exit; ++t) {
		vec g = grad(pos);
		pw1 *= beta1;
		pw2 *= beta2;
		for (int i = 0; i < dim; ++i) {
			m[i] = m[i] * beta1 + g[i] * (1 - beta1);
			v[i] = v[i] * beta2 + g[i] * g[i] * (1 - beta2);
			double update = m[i] / (1 - pw1);
			double factor = lr / (sqrt(v[i] / (1 - pw2)) + 1e-8);
			pos[i] -= update * factor;
		}
		lr *= decay;
	}
	return pos;
}

int main() {
	auto grad = [](vec A) {
		double x = A[0], y = A[1];
		return vec{ 2 * y + -4 / (x * x), 2 * x + -4 / (y * y) };
	};
	auto ans = Adam(grad, vec{ 1, 1 }, 0.01, 0.999, 1e-8);
	printf("%.10f %.10f\n", ans[0], ans[1]); //1.2599210498948732
	return 0;
}

﻿#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <random>
#include <tuple>
#include <vector>
#include <map>
using namespace std;
const int nrow = 10, ncol = 10, max_state = nrow * ncol, max_action = 4;
const int dr[4] = { -1, 1, 0, 0 };
const int dc[4] = { 0, 0, -1, 1 };
struct CliffWalkingEnv {
	char s[11][11];
	int x, y;
	vector<pair<int, int>> path;
	CliffWalkingEnv() {
		reset();
	}
	int reset() {
		x = 0, y = 0;
		path.clear();
		path.emplace_back(x, y);
		memset(s, 0, sizeof(s));
		for (int i = 0; i < nrow; ++i) {
			for (int j = 0; j < ncol; ++j) {
				s[i][j] = '.';
			}
		}
		for (int i = 0; i < 5; ++i) {
			for (int j = 1; j < ncol - 1; ++j) {
				s[i][j] = '#';
			}
		}
		return x * ncol + y;
	}
	void print() {
		char t[11][11];
		memcpy(t, s, sizeof(s));
		for (auto [x, y] : path) {
			if (t[x][y] >= '1' && t[x][y] < '9')
				t[x][y] += 1;
			else
				t[x][y] = '1';
		}
		for (int i = 0; i < nrow; ++i)
			printf("%s\n", t[i]);
		printf("\n");
	}
	tuple<int, int, int> step(int number) {
		int nx = x + dr[number], ny = y + dc[number];
		if (nx >= 0 && nx < nrow && ny >= 0 && ny < ncol)
			x = nx, y = ny;
		int reward = -1, done = false;
		if (s[x][y] == '#') {
			reward = -100;
			done = true;
		}
		if (x == 0 && y == ncol - 1)
			done = true;
		path.emplace_back(x, y);
		return make_tuple(x * ncol + y, reward, done);
	}
} env;

const double alpha = 1e-1; /*学习率*/
const double gamma = 0.9; /*折扣因子*/
const double epsilon = 1e-2; /*epsilon-greedy*/
const int N = 10; //Q-Planning的次数
const int max_episode = 200; //训练多少轮
uniform_real_distribution<double> p;
uniform_int_distribution<int> d;
default_random_engine e;
double Q[max_state][max_action];
map<pair<int, int>, int> id;
vector<tuple<int, int, int, int>> model;
int epsilon_greedy(int state) { /*基于epsilon-greedy选择动作*/
	if (p(e) < epsilon)
		return d(e) % max_action;
	return max_element(Q[state], Q[state] + max_action) - Q[state];
}
void learn(int s0, int a0, int r, int s1) {
	auto td_error = r + gamma * *max_element(Q[s1], Q[s1] + max_action) - Q[s0][a0];
	Q[s0][a0] += alpha * td_error;
}
void update(int s0, int a0, int r, int s1) { 
	learn(s0, a0, r, s1);
	pair<int, int> pr(s0, a0);
	if (!id.count(pr)) {
		id[pr] = model.size();
		model.emplace_back(s0, a0, r, s1);
	}
	else {
		model[id[pr]] = make_tuple(s0, a0, r, s1);
	}
	for (int i = 0; i < N; ++i) {
		int idx = d(e) % model.size();
		auto [s0, a0, r, s1] = model[idx];
		learn(s0, a0, r, s1);
	}
}
void DynaQ() {
	for (int i = 0; i < max_episode; ++i) {
		int state = env.reset();
		for (;;) {
			int action = epsilon_greedy(state);
			auto [next_state, reward, done] = env.step(action);
			update(state, action, reward, next_state);
			state = next_state;
			if (done)
				break;
		}
		env.print();
	}
}
int main() {
	DynaQ();
	return 0;
}

﻿#include <iostream>
#include <algorithm>
#include <vector>
#include <numeric>
#include <iterator>
#include <random>
#include <limits>
#include <cmath>
#include <array>
#pragma GCC optimize("Ofast")
#pragma GCC target("avx512bw,avx512vl")
#pragma GCC optimization("unroll-loops")
using namespace std;
/*
	vec：待聚类的向量组
	n：向量个数
	dimension：向量维度
	belong：向量属于哪一个簇
	center：算法计算出的每个簇的中心向量
	k：簇的个数
	iterations：迭代次数
*/
template<typename T, int MAXN, int MAXM, int MAXD>
inline void kmeans(const T(&vec)[MAXN][MAXD], int n, int dimension, int(&belong)[MAXN], T(&center)[MAXM][MAXD], int k, int iterations) {
	mt19937 engine;
	vector<int> indices(n), choices;
	iota(indices.begin(), indices.end(), 0);
	sample(indices.begin(), indices.end(), back_inserter(choices), k, engine);
	for (int i = 0; i < k; ++i) {
		copy(vec[choices[i]], vec[choices[i]] + dimension, center[i]);
	}
	for (int t = 0; t < iterations; ++t) { //迭代iterations轮
		for (int i = 0; i < n; ++i) {
			T best = numeric_limits<T>::max();
			for (int j = 0; j < k; ++j) {
				T distance = 0;
				for (int d = 0; d < dimension; ++d) {
					distance += (vec[i][d] - center[j][d]) * (vec[i][d] - center[j][d]);
				}
				if (distance < best) {
					best = distance;
					belong[i] = j;
				}
			}
		}
		if (t + 1 != iterations) {
			int sz[MAXM] = {};
			for (int j = 0; j < k; ++j) {
				for (int d = 0; d < dimension; ++d) {
					center[j][d] = 0;
				}
			}
			for (int i = 0; i < n; ++i) {
				sz[belong[i]] += 1;
				for (int d = 0; d < dimension; ++d) {
					center[belong[i]][d] += vec[i][d];
				}
			}
			for (int j = 0; j < k; ++j) {
				for (int d = 0; d < dimension; ++d) {
					center[j][d] /= sz[j];
				}
			}
		}
	}
}
template<typename T, int MAXN, int MAXM, int MAXD>
inline void kmeans_plusplus(const T(&vec)[MAXN][MAXD], int n, int dimension, int(&belong)[MAXN], T(&center)[MAXM][MAXD], int k, int iterations) {
	mt19937 engine;
	vector<T> distance(n, numeric_limits<T>::max());
	vector<bool> mask(n);
	mask[0] = true;
	copy(vec[0], vec[0] + dimension, center[0]);
	for (int j = 1; j < k; ++j) {
		for (int i = 0; i < n; ++i) {
			T dist = 0;
			for (int d = 0; d < dimension; ++d) {
				dist += (vec[i][d] - center[j - 1][d]) * (vec[i][d] - center[j - 1][d]);
			}
			distance[i] = min(distance[i], dist);
		}
		vector<T> sum(n);
		for (int i = 1; i < n; ++i) {
			sum[i] = sum[i - 1] + (mask[i] ? 0.0 : distance[i]);
		}
		uniform_real_distribution<T> gen(0, sum[n - 1]);
		auto index = lower_bound(sum.begin(), sum.end(), gen(engine)) - sum.begin();
		mask[index] = true;
		copy(vec[index], vec[index] + dimension, center[j]);
	}
	for (int t = 0; t < iterations; ++t) { //迭代iterations轮
		for (int i = 0; i < n; ++i) {
			T best = numeric_limits<T>::max();
			for (int j = 0; j < k; ++j) {
				T distance = 0;
				for (int d = 0; d < dimension; ++d) {
					distance += (vec[i][d] - center[j][d]) * (vec[i][d] - center[j][d]);
				}
				if (distance < best) {
					best = distance;
					belong[i] = j;
				}
			}
		}
		if (t + 1 != iterations) {
			int sz[MAXM] = {};
			for (int j = 0; j < k; ++j) {
				for (int d = 0; d < dimension; ++d) {
					center[j][d] = 0;
				}
			}
			for (int i = 0; i < n; ++i) {
				sz[belong[i]] += 1;
				for (int d = 0; d < dimension; ++d) {
					center[belong[i]][d] += vec[i][d];
				}
			}
			for (int j = 0; j < k; ++j) {
				for (int d = 0; d < dimension; ++d) {
					center[j][d] /= sz[j];
				}
			}
		}
	}
}

constexpr int MAXN = 50000, MAXD = 1024, MAXM = 100;
double vec[MAXN][MAXD], center[MAXM][MAXD];
int belong[MAXN];
int main() {
