﻿#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <vector>
#include <array>
#include <cmath>
#include <ctime>
using namespace std;
const int maxn = 210000;
const int maxdim = 1001;
const double eps = 1e-8;
using matrix = double[maxdim][maxdim];
using vec = array<double, maxdim>;
using pair_t = pair<double, vec>;
struct PCA {
	matrix A, V;
	int column[maxdim], n;
	void update(int r, int c, double v) {
		A[r][c] = v;
		if (column[r] == c || fabs(A[r][c]) > fabs(A[r][column[r]])) {
			for (int i = 0; i < n; ++i) if (i != r)
				if (fabs(A[r][i]) > fabs(A[r][column[r]]))
					column[r] = i;
		}
	}
	void Jacobi() {
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j)
				V[i][j] = 0;
			V[i][i] = 1;
			column[i] = (i == 0 ? 1 : 0);
		}
		for (int i = 0; i < n; ++i) 
			for (int j = 0; j < n; ++j) 
				if (j != i && fabs(A[i][j]) > fabs(A[i][column[i]]))
					column[i] = j;
		for (int T = 0; ; ++T) { //迭代次数限制
			int x, y;
			double val = 0;
			for (int i = 0; i < n; ++i)
				if (fabs(A[i][column[i]]) > val)
					val = fabs(A[i][column[i]]), x = i, y = column[i];
			if (val < eps) //精度限制
				break;
			double phi = atan2(-2 * A[x][y], A[y][y] - A[x][x]) / 2;
			double sinp = sin(phi), cosp = cos(phi);
			for (int i = 0; i < n; ++i) if (i != x && i != y) {
				double a = A[x][i] * cosp + A[y][i] * sinp;
				double b = A[x][i] * -sinp + A[y][i] * cosp;
				update(x, i, a);
				update(y, i, b);
			}
			for (int i = 0; i < n; ++i) if (i != x && i != y) {
				double a = A[i][x] * cosp + A[i][y] * sinp;
				double b = A[i][x] * -sinp + A[i][y] * cosp;
				update(i, x, a);
				update(i, y, b);
			}
			for (int i = 0; i < n; ++i) {
				double a = V[i][x] * cosp + V[i][y] * sinp;
				double b = V[i][x] * -sinp + V[i][y] * cosp;
				V[i][x] = a, V[i][y] = b;
			}
			double a = A[x][x] * cosp * cosp + A[y][y] * sinp * sinp + 2 * A[x][y] * cosp * sinp;
			double b = A[x][x] * sinp * sinp + A[y][y] * cosp * cosp - 2 * A[x][y] * cosp * sinp;
			double tmp = (A[y][y] - A[x][x]) * sin(2 * phi) / 2 + A[x][y] * cos(2 * phi);
			update(x, y, tmp);
			update(y, x, tmp);
			A[x][x] = a, A[y][y] = b;
		}
	}
	//a 为输入向量组
	//n 为向量的维数
	//center 指针用来保存输入向量组的中心点
	//返回特征值和特征向量的pair，按照特征值从大到小排序
	//特征值是各个点在对应特征向量方向的坐标平方和，除以(a.size() - 1)为方差。
	auto solve(vector<vec> a, int n, vec* center = nullptr) {
		this->n = n;
		vec s = {};
		for (int i = 0; i < a.size(); ++i)
			for (int j = 0; j < n; ++j)
				s[j] += a[i][j];
		for (int j = 0; j < n; ++j)
			s[j] /= a.size();
		for (int i = 0; i < a.size(); ++i)
			for (int j = 0; j < n; ++j)
				a[i][j] -= s[j];
		if (center) *center = s;
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j) {
				A[i][j] = 0;
				for (int k = 0; k < a.size(); ++k)
					A[i][j] += a[k][i] * a[k][j];
			}
		}
		Jacobi();
		vector<pair_t> result;
		for (int i = 0; i < n; ++i)
			result.emplace_back(A[i][i], vec());
		for (int i = 0; i < n; ++i)
			for (int j = 0; j < n; ++j)
				result[i].second[j] = V[j][i];
		sort(result.begin(), result.end(), greater<pair_t>());
		return result;
	}
}pca;
int main() { //1329070654.526
	freopen("in.txt", "r", stdin);
	vector<vec> a;
	int n, m;
	scanf("%d %d", &n, &m);
	for (int i = 0; i < n; ++i) {
		vec v = {};
		for (int j = 0; j < m; ++j)
			scanf("%lf", &v[j]);
		a.push_back(v);
	}
	auto now = clock();
	auto result = pca.solve(a, m);
	for (int i = 0; i < m; ++i)
		printf("%.3f\n", result[i].first);
	printf("time: %f\n", double(clock() - now) / CLOCKS_PER_SEC);
	return 0;
}

#include <vector>
#include <algorithm>
using namespace std;
struct state {
	bool inFinal();
	int score();
	void expand(int, vector<state>&);
};
int search(state& s, int player, int alpha, int beta) {
	if (s.inFinal()) {
		return s.score();
	}
	vector<state> children;
	s.expand(player, children);
	for (auto child : children) {
		int value = search(child, player ^ 1, alpha, beta);
		if (!player) {
			alpha = max(alpha, value);
		}
		else {
			beta = min(beta, value);
		}
		if (beta <= alpha) {
			break;
		}
	}
	return !player ? alpha : beta;
}

﻿#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;
const int INF = 100000000;
int nrows, ncols;
int G[10][10];
// 插头编号：0表示无插头，1表示和数字2连通，2表示和数字3连通
struct State {
    int up[9]; // up[i](0<=i<m)表示第i列处轮廓线上方的插头编号
    int left; // 当前格（即下一个要放置的方格）左侧的插头
    // 三进制编码
    int encode() const {
        int key = left;
        for (int i = 0; i < ncols; i++)
            key = key * 3 + up[i];
        return key;
    }
    // 在(row,col)处放一个新方格。UDLR分别为该方格上下左右四个边界上的插头编号
    // 产生的新状态存放在T里，成功返回true，失败返回false
    bool next(int row, int col, int U, int D, int L, int R, State& T) const {
        if (row == nrows - 1 && D != 0) return false; // 最下行下方不能有插头
        if (col == ncols - 1 && R != 0) return false; // 最右列右边不能有插头
        int must_left = (col > 0 && left != 0); // 是否必须要有左插头
        int must_up = (row > 0 && up[col] != 0); // 是否必须要有上插头
        if ((must_left && L != left) || (!must_left && L != 0)) return false; // 左插头不匹配
        if ((must_up && U != up[col]) || (!must_up && U != 0)) return false; // 上插头不匹配
        if (must_left && must_up && left != up[col]) return false; // 若左插头和上插头都存在，二者必须匹配
        // 产生新状态。实际上只有当前列的下插头和left插头有变化
        for (int i = 0; i < ncols; i++) T.up[i] = up[i];
        T.up[col] = D;
        T.left = R;
        return true;
    }
};
int memo[9][9][59049]; // 3^10
// 当前要放置格子(row, col)，状态为S。返回最小总长度
int rec(int row, int col, const State& S) {
    if (col == ncols) { col = 0; row++; }
    if (row == nrows) return 0;
    int key = S.encode();
    int& res = memo[row][col][key];
    if (res >= 0) return res;
    res = INF;
    State T;
    if (G[row][col] <= 1) { // 空格（0）或者障碍格（1）
        if (S.next(row, col, 0, 0, 0, 0, T)) res = min(res, rec(row, col + 1, T)); // 整个格子里都不连线
        if (G[row][col] == 0) // 如果是空格，可以连线。由于线不能分叉，所以这条线一定连接格子的某两个边界（6种情况）
            for (int t = 1; t <= 2; t++) { // 枚举线的种类。t=1表示2线，t=2表示3线
                if (S.next(row, col, t, t, 0, 0, T)) res = min(res, rec(row, col + 1, T) + 2); // 上<->下
                if (S.next(row, col, t, 0, t, 0, T)) res = min(res, rec(row, col + 1, T) + 2); // 上<->左
                if (S.next(row, col, t, 0, 0, t, T)) res = min(res, rec(row, col + 1, T) + 2); // 上<->右
                if (S.next(row, col, 0, t, t, 0, T)) res = min(res, rec(row, col + 1, T) + 2); // 下<->左
                if (S.next(row, col, 0, t, 0, t, T)) res = min(res, rec(row, col + 1, T) + 2); // 下<->右
                if (S.next(row, col, 0, 0, t, t, T)) res = min(res, rec(row, col + 1, T) + 2); // 左<->右
            }
    }
    else {
        int t = G[row][col] - 1; // 数字为2和3，但插头类型是1和2，所以要减1
        // 由于线不能分叉，所以这条线一定连接格子中间的数字和某一个边界（4种情况）
        if (S.next(row, col, t, 0, 0, 0, T)) res = min(res, rec(row, col + 1, T) + 1); // 从上边界出来
        if (S.next(row, col, 0, t, 0, 0, T)) res = min(res, rec(row, col + 1, T) + 1); // 从下边界出来
        if (S.next(row, col, 0, 0, t, 0, T)) res = min(res, rec(row, col + 1, T) + 1); // 从左边界出来
        if (S.next(row, col, 0, 0, 0, t, T)) res = min(res, rec(row, col + 1, T) + 1); // 从右边界出来
    }
    return res;
}
int main() {
    while (scanf("%d%d", &nrows, &ncols) == 2 && nrows && ncols) {
        for (int i = 0; i < nrows; i++)
            for (int j = 0; j < ncols; j++)
                scanf("%d", &G[i][j]);
        State S;
        memset(&S, 0, sizeof(S));
        memset(memo, -1, sizeof(memo));
        int ans = rec(0, 0, S);
        if (ans == INF) ans = 0;
        printf("%d\n", ans / 2);
    }
    return 0;
}
