using namespace std;
int n, m, s; //点数、边数、起点
namespace BellmanFord { // O(nm)
	const int maxn = 1001;
	const int maxedges = 110000;
	int d[maxn], x[maxedges], y[maxedges], w[maxedges];
	void BellmanFord() {
		memset(d, 0x3f, sizeof(d));
		d[s] = 0;
		for (int k = 1; k < n; ++k)
			for (int i = 1; i <= m; ++i)
