	for (int i = 1; i <= m; ++i)
		scanf("%d %d %d", &from[i], &to[i], &weight[i]);
	int ans = kruskal();
	if (ans == -1)
		puts("orz");
	else
		printf("%d\n", ans);
	return 0;
}

