	//若有多组数据应将G和result清空，调用完euler之后G中的边会被删除
	multiset<int> G[maxn];
	vector<pair<int, int>> result;
	void dfs(int x) {
		while (G[x].size()) {
			auto iter = G[x].begin();
			auto y = *iter;
			G[x].erase(iter);
			G[y].erase(G[y].find(x));
			dfs(y);
			result.emplace_back(x, y);
		}
