	default_random_engine e;
	uniform_int_distribution<int> d(0, INT_MAX);
	for (int i = 0; i < n; ++i)
		A[i] = B[i] = d(e);
	printf("start....\n");
	auto start = clock();
	sort(A, A + n);
	printf("std::sort: %f\n", static_cast<double>(clock() - start) / CLOCKS_PER_SEC);
	start = clock();
	RadixSort_Int::sort(B, n);
	printf("std::sort: %f\n", static_cast<double>(clock() - start) / CLOCKS_PER_SEC);
