        long long ans = 0, val = 1;
        for (int i = 0; i < n; ++i) {
            ans = (ans + (pos[i] + 1) * val) % mod;
            val = val * 1112 % mod;
        }
        printf("%lld\n", ans);
    }
	return 0;
}

