void init() {
	memset(par, 0, sizeof(par));
	memset(ch, 0, sizeof(ch));
	memset(fa, 0, sizeof(fa));
	memset(go, 0, sizeof(go));
	memset(pos, -1, sizeof(pos));
	cur = 1;
	root = last = newstate(0);
}
void extend(int w, int index) {
	int x = last;
	int nx = newstate(len[x] + 1);
	while (x && !go[x][w])
		go[x][w] = nx, x = par[x];
	if (!x)
		par[nx] = root, fa[nx] = root;
	else {
		int y = go[x][w];
		if (len[x] + 1 == len[y])
			par[nx] = y, fa[nx] = y;
		else {
			int ny = newstate(len[x] + 1);
			memcpy(go[ny], go[y], sizeof(go[y]));
			fa[ny] = par[y], par[ny] = par[y];
			cut(y);
			pos[ny] = pos[y];
			fa[y] = ny, par[y] = ny;
			fa[nx] = ny, par[nx] = ny;
			while (x && go[x][w] == y)
				go[x][w] = ny, x = par[x];
		}
	}
	last = nx;
	access(last, index);
	splay(last);
	pos[last] = index;
}
char s[maxn];
vector<pair<int, int>> Q[maxn]; //多组数据时要清空
long long answer[maxn];
int main() {
	//freopen("in.txt", "r", stdin);
	scanf("%s", s);
	int n = strlen(s);
	init();
	tree.init(n + 10);
	int m;
	scanf("%d", &m);
	for (int i = 0; i < m; ++i) {
		int L, R;
		scanf("%d %d", &L, &R);
		--L; --R;
		Q[R].emplace_back(L, i);
	}
	for (int i = 0; i < n; ++i) {
		extend(s[i] - 'a', i);
		for (auto [L, id] : Q[i])
			answer[id] = tree.query(L);
	}
	for (int i = 0; i < m; ++i)
		printf("%lld\n", answer[i]);
	return 0;
}

﻿/*
len[i]表示编号为i的节点表示的回文串的长度（一个节点表示一个回文串）
fail[i]表示结点i失配以后跳转到的最长后缀回文串对应的结点
cnt[i]表示结点i对应的字符串出现的次数（建树时求出的不是完全的，最后calc()函数跑一遍以后才是正确的）
num[i]表示以结点i表示的最长回文串的最右端点为回文串结尾的回文串个数
num[i]也表示结点i在fail树中的深度
若要判断回文自动机中是否包含回文串P[0, m - 1]，则根据P的长度是奇数还是偶数来选择根结点（长度为偶数的回文串以0为根结点，长度为奇数的回文串以1为根结点），
然后将字符串P[m / 2, m - 1]输入自动机，到达了结点node，自动机包含回文串P当且仅当len[node] == m。
*/
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <iostream>
#include <algorithm>
using namespace std;
const int maxn = 300010; //maxn至少为字符串最大可能长度的两倍
long long ans = 0; //统计当前的字符串中有多少个回文串（位置不同即不同）
struct Palindromic_Tree {
	int ch[maxn][26], fail[maxn], info[maxn];
	int cnt[maxn], num[maxn], len[maxn];
	int last[2], cur, L, R;
	void init() {
		memset(ch, 0, sizeof(ch));
		memset(cnt, 0, sizeof(cnt));
		memset(info, -1, sizeof(info)); //info的初始值为不会出现在输入字符串中的值即可
		len[1] = -1;
		cur = fail[0] = last[1] = 1;
		last[0] = 0;
		L = maxn / 2;
		R = L - 1;
	}
	int get_fail(int x, int back) {
		int k = back ? R : L;
		int tp = back ? 1 : -1;
		while (info[k - (len[x] + 1) * tp] != info[k])
			x = fail[x];
		return x;
	}
	void insert(int w, int back) { //back为1则插入w到字符串的结尾，为0则插入到开头。
		if (back) info[++R] = w;
		else info[--L] = w;
		int p = get_fail(last[back], back);
		if (!ch[p][w]) {
			int u = ++cur;
			fail[u] = ch[get_fail(fail[p], back)][w];
			len[u] = len[p] + 2;
			ch[p][w] = u;
			num[u] = num[fail[u]] + 1;
		}      
		last[back] = ch[p][w];
		if (len[last[back]] == R - L + 1)
			last[back ^ 1] = last[back];
		ans += num[last[back]]; //当前结点的插入会使得字符串中新增num[last[back]]个新的回文串
		cnt[last[back]]++;
	}
	void calc() {
		for (int i = cur; i >= 2; --i)
			cnt[fail[i]] += cnt[i];
	}
}tree;
int main(){
	//freopen("in.txt", "r", stdin);
	int n;
	while (scanf("%d", &n) == 1) {
		tree.init(); ans = 0;
		while (n--) {
			int tp;
			scanf("%d", &tp);
			if (tp == 1) {
				char c;
				scanf(" %c", &c);
				tree.insert(c - 'a', false);
			}
			else if (tp == 2) {
				char c;
				scanf(" %c", &c);
				tree.insert(c - 'a', true);
			}
			else if (tp == 3) {
				printf("%d\n", tree.cur - 1);
			}
			else {
				printf("%lld\n", ans);
			}
		}
	}
}

﻿#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <string>
using namespace std;
const int maxn = 1110000;
const double alpha = 0.6;
struct SuffixBalancedTree {
	string data;
	double val[maxn], left, right;
	int sz[maxn], ch[maxn][2], root;
	int* pos, length, A[maxn];
	void init() {
		data.resize(1);
		root = 0;
	}
	void pushup(int x) {
		sz[x] = sz[ch[x][0]] + sz[ch[x][1]] + 1;
	}
	void dfs(int x) {
		if (!x) return;
		dfs(ch[x][0]);
		A[++length] = x;
		dfs(ch[x][1]);
	}
	int build(int a, int b, double L, double R) {
		if (a > b) return 0;
		int mid = (a + b) >> 1;
		int x = A[mid];
		sz[x] = b - a + 1;
		val[x] = (L + R) / 2;
		ch[x][0] = build(a, mid - 1, L, val[x]);
		ch[x][1] = build(mid + 1, b, val[x], R);
		return x;
	}
	void add(int& x, double L, double R) {
		if (!x) {
			x = data.size() - 1;
			ch[x][0] = ch[x][1] = 0;
			val[x] = (L + R) / 2;
			sz[x] = 1;
			return;
		}
		int y = data.size() - 1;
		if (data[y] < data[x] || data[y] == data[x] && val[y - 1] < val[x - 1])
			add(ch[x][0], L, val[x]);
		else
			add(ch[x][1], val[x], R);
		pushup(x);
		if (sz[ch[x][0]] > sz[x] * alpha || sz[ch[x][1]] > sz[x] * alpha)
			pos = &x, left = L, right = R;
	}
	void push_front(char c) { //向开头添加一个新的字符之后会改变其他位置的下标
		data.push_back(c);
		pos = nullptr;
		add(root, 0, 1);
		if (pos) {
			length = 0;
			dfs(*pos);
			*pos = build(1, length, left, right);
		}
	}
	int merge(int x, int y) {
		if (!x || !y) 
			return x | y;
		if (sz[x] > sz[y]) {
			ch[x][1] = merge(ch[x][1], y);
			pushup(x);
			return x;
		}
		else {
			ch[y][0] = merge(x, ch[y][0]);
			pushup(y);
			return y;
		}
	}
	void del(int& x) {
		const int y = data.size() - 1;
		sz[x] -= 1;
		if (x == y)
			x = merge(ch[x][0], ch[x][1]);
		else if (val[y] < val[x])
			del(ch[x][0]);
		else
			del(ch[x][1]);
	}
	void pop_front() {
		del(root);
		data.pop_back();
	}
	double weight(int index) { //返回下标index的权值，权值越小，字典序越小（下标从1开始）
		return val[data.size() - index];
	}
	int rank(int index) { //返回下标index的排名（下标从1开始）
		double key = weight(index);
		int ret = 0, x = root;
		while (x) {
			if (key < val[x])
				x = ch[x][0];
			else
				ret += sz[ch[x][0]] + 1, x = ch[x][1];
		}
		return ret;
	}
	int rank(const char *s) { //返回字典序小于s的后缀的个数
		int ret = 0, x = root, n = strlen(s);
		while (x) {
			int L = min(x, n) + 1;
			int flag = 0;
			for (int i = 0; i < L; ++i) {
				if (s[i] != data[x - i]) {
					flag = s[i] - data[x - i];
					break;
				}
			}
			if (flag <= 0)
				x = ch[x][0];
			else
				ret += sz[ch[x][0]] + 1, x = ch[x][1];
		}
		return ret;
	}
}tree;
