	return 0;
}

﻿/*
1.	rank[i]表示下标i的排名（排名从0开始）。
2.	sa[i]表示第i小的后缀的下标（i从0开始）。
3.	height[i]表示sa[i - 1]与sa[i]的最长公共前缀。
*/
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <iostream>
#include <algorithm>
#include <vector>
#include <string>
using namespace std;
const int maxn = 210000; //maxn应当开到最大字符串长度的两倍，否则(1)处下标访问可能越界。
const int maxlog = 20;
struct Suffix_Array {
	char s[maxn];
	int sa[maxn], rank[maxn], height[maxn];
	int t[maxn], t2[maxn], c[maxn], n;
	void init(const char* str) {
		strcpy(s, str);
		n = strlen(s);
		memset(t, 0, sizeof(int) * (2 * n + 10));  //为了保证(1)处访问越界时得到的数组值恒为0，应当将t和t2数组清空
		memset(t2, 0, sizeof(int) * (2 * n + 10));
	}
	void build_sa(int m = 256) {
		int* x = t, * y = t2;
		for (int i = 0; i < m; ++i) c[i] = 0;
		for (int i = 0; i < n; ++i) c[x[i] = s[i]]++;
		for (int i = 1; i < m; ++i) c[i] += c[i - 1];
		for (int i = n - 1; i >= 0; --i) sa[--c[x[i]]] = i;
		for (int k = 1; k <= n; k <<= 1) {
			int p = 0;
			for (int i = n - 1; i >= n - k; --i) y[p++] = i;
			for (int i = 0; i < n; ++i) if (sa[i] >= k) y[p++] = sa[i] - k;
			for (int i = 0; i < m; ++i) c[i] = 0;
			for (int i = 0; i < n; ++i) c[x[y[i]]]++;
			for (int i = 1; i < m; ++i) c[i] += c[i - 1];
			for (int i = n - 1; i >= 0; --i) sa[--c[x[y[i]]]] = y[i];
			swap(x, y);
			p = 1; x[sa[0]] = 0;
			for (int i = 1; i < n; ++i)
				x[sa[i]] = y[sa[i - 1]] == y[sa[i]] && y[sa[i - 1] + k] == y[sa[i] + k] ? p - 1 : p++; //(1)
			if (p >= n) break;
			m = p;
		}
	}
	void getheight() {
		int k = 0;
		for (int i = 0; i < n; ++i) rank[sa[i]] = i;
		for (int i = 0; i < n; ++i) if (rank[i] > 0) {
			if (k) k--;
			int j = sa[rank[i] - 1];
			while (i + k < n && j + k < n && s[i + k] == s[j + k]) k++;
			height[rank[i]] = k;
		}
	}
	int d[maxn][maxlog], log[maxn];
	void RMQ_init() {
		log[0] = -1;
		for (int i = 1; i <= n; ++i)
			log[i] = log[i / 2] + 1;
		for (int i = 0; i < n; ++i)
			d[i][0] = height[i];
		for (int j = 1; j <= log[n]; ++j)
			for (int i = 0; i + (1 << j) - 1 < n; ++i)
				d[i][j] = min(d[i][j - 1], d[i + (1 << (j - 1))][j - 1]);
	}
	int lcp(int i, int j) { //返回下标i开始的后缀与下标j开始的后缀的最长公共前缀。
		if (i == j)
			return n - i;
		if (rank[i] > rank[j])
			swap(i, j);
		int x = rank[i] + 1, y = rank[j];
		int k = log[y - x + 1];
		return min(d[x][k], d[y - (1 << k) + 1][k]);
	}
	pair<int, int> locate(int l, int r) {
		//返回一个最长的区间[L, R]使得sa中下标从L到R的所有后缀都以s[l, r]为前缀。
		int pos = rank[l], length = r - l + 1;
		int L = 0, R = pos;
		while (L < R) {
			int M = L + (R - L) / 2;
			if (lcp(l, sa[M]) >= length) R = M;
			else L = M + 1;
		}
		int tmp = L;
		L = pos, R = n - 1;
		while (L < R) {
			int M = L + (R - L + 1) / 2;
			if (lcp(l, sa[M]) >= length) L = M;
			else R = M - 1;
		}
		return make_pair(tmp, L);
	}
	pair<int, int> locate(vector<pair<int, int>> ranges) {
		//将ranges中的所有下标区间对应的子串拼接到一起，得到字符串T，
		//返回一个最长的区间[L, R]使得sa中下标从L到R的所有后缀都以T为前缀，
		//无解返回{ 0, -1 }。
		int l = 0, r = n - 1, pos = 0;
		for (auto [x, y] : ranges) {
			int L = l, R = r, len = y - x + 1;
			while (L < R) {
				int M = L + (R - L) / 2;
				int pre = sa[M] + pos < n ? lcp(sa[M] + pos, x) : 0;
				int ch1 = s[sa[M] + pos + pre], ch2 = s[x + pre];
				if (pre >= len || ch1 > ch2) R = M;
				else L = M + 1;
			}
			int left = L;
			L = l, R = r;
			while (L < R) {
				int M = L + (R - L + 1) / 2;
				int pre = sa[M] + pos < n ? lcp(sa[M] + pos, x) : 0;
				int ch1 = s[sa[M] + pos + pre], ch2 = s[x + pre];
				if (pre >= len || ch1 < ch2) L = M;
				else R = M - 1;
			}
			int right = L;
			if (sa[left] + pos > n || lcp(sa[left] + pos, x) < len)
				return make_pair(0, -1);
			else
				l = left, r = right;
			pos += len;
		}
		return make_pair(l, r);
	}
	pair<int, int> go(int x, int y, int h, char c) {
		//设sa数组中区间[x, y]的最长公共前缀至少为h，则返回区间中的后缀i满足s[i + h] == c
		//若要识别s中所有以c开头的后缀，则调用go(0, n - 1, 0, c)
		int L = x, R = y;
		while (L < R) {
			int M = L + (R - L) / 2;
			if (sa[M] + h < n && s[sa[M] + h] >= c) R = M;
			else L = M + 1;
		}
		int tmp = L;
		R = y;
		while (L < R) {
			int M = L + (R - L + 1) / 2;
			if (s[sa[M] + h] == c) L = M;
			else R = M - 1;
		}
		if (sa[L] + h >= n || s[sa[L] + h] != c)
			return { 0, -1 }; //空区间
		return { tmp, L };
	}
	pair<int, int> go(int x, int y, int h, const string &str) {
		//设sa数组中区间[x, y]的最长公共前缀至少为h，则返回区间中的后缀i满足s[i + h + j] == str[j]
		//若要识别s中所有以str开头的后缀，则调用go(0, n - 1, 0, str)
		for (auto c : str) {
			int L = x, R = y;
			while (L < R) {
				int M = L + (R - L) / 2;
				if (sa[M] + h < n && s[sa[M] + h] >= c) R = M;
				else L = M + 1;
			}
			x = L, R = y;
			while (L < R) {
				int M = L + (R - L + 1) / 2;
				if (s[sa[M] + h] == c) L = M;
				else R = M - 1;
			}
			if (sa[L] + h >= n || s[sa[L] + h] != c)
				return { 0, -1 }; //空区间
			y = L;
			h += 1;
		}
		return { x, y };
	}
	pair<int, int> go_rev(int x, int y, char c) {
		//设区间[x, y]表示sa中的一个区间，将[x, y]中的每个后缀都往前走一个字符c，
		//得到一个新的连续区间并返回，注意这个新区间不一定是[x, y]的子区间
		//注意：因为sa[0, n-1]不包含空串，所以go(0, n - 1, 0, c) != go_rev(0, n - 1, c)
		int L = 0, R = n - 1;
		while (L < R) {
			int M = L + (R - L) / 2;
			if (s[sa[M]] < c || s[sa[M]] == c && (sa[M] == n - 1 || rank[sa[M] + 1] < x))
				L = M + 1;
			else
				R = M;
		}
		int tmp = L;
		R = n - 1;
		while (L < R) {
			int M = L + (R - L + 1) / 2;
			if (s[sa[M]] > c || s[sa[M]] == c && rank[sa[M] + 1] > y)
				R = M - 1;
			else
				L = M;
		}
		if (s[sa[L]] != c || rank[sa[L] + 1] < x || rank[sa[L] + 1] > y)
			return { 0, -1 }; //空区间
		return { tmp, L };
	}
}arr;
int main() {
	static char s[maxn];
	scanf("%s", s);
	int n = strlen(s), Q;
	scanf("%d", &Q);
	arr.init(s);
	arr.build_sa();
	arr.getheight();
	arr.RMQ_init();
	while (Q--) {
		int x, y, a, b;
		scanf("%d %d %d %d", &x, &y, &a, &b); --x; --y; --a; --b;
		auto [L, R] = arr.locate(vector<pair<int, int>>{make_pair(x, y), make_pair(a, b)});
		printf("%d\n", R - L + 1);
	}
}

﻿/*
1.	ch[u][c]表示从结点u出发走字符c后到达的结点（0为空结点）。
2.	len[u]表示从结点u的父结点走到u的这条边的长度（可能为0）。
3.	从结点u的父结点走到u的字符串的下标区间为[start[u], start[u] + len[u] - 1]。
4.	link[u]记录结点u的后缀链接，若内部结点u表示的字符串为[s, t]，则其后缀链接的结点对应字符串为[s+1, t]。
5.	depth[u]表示结点u的加权深度，dep[u]表示结点的不加权深度（根结点到u经过的边数）。
6.	s数组记录输入的字符串。
7.	对于叶结点pos[i]表示结点i对应的后缀的下标，非叶结点pos[i]为-1。
8.	node是pos的反函数，node[i]表示后缀s[i, m]对应的结点（下标从1开始）。
*/
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <ctime>
#include <vector>
#include <cassert>
using namespace std;
const int sigma_size = 26;
const int maxlog = 20;
const int maxn = 4e5 + 10;
const int inf = 1e9;
struct Suffix_Tree {
public: //后缀树基本结构
	int ch[maxn][sigma_size + 1], len[maxn], start[maxn], link[maxn], depth[maxn], s[maxn], cur, n, rem, now;
	int pos[maxn], node[maxn];
	void init() {
		memset(ch, 0, sizeof(ch));
		cur = now = 1;
		n = rem = 0;
		len[0] = inf;
		depth[0] = 0;
	}
	int newnode(int p, int w, int d) {
		start[++cur] = p;
		len[cur] = w;
		depth[cur] = d;
		link[cur] = 1;
		return cur;
	}
	void extend(int x) { //0 <= x <= sigma_size
		s[++n] = x, ++rem;
		for (int last = 1; rem; now == 1 ? --rem : now = link[now]) {
			while (rem > len[ch[now][s[n - rem + 1]]])
				rem -= len[now = ch[now][s[n - rem + 1]]];
			int ed = s[n - rem + 1];
			int& v = ch[now][ed];
			int c = s[start[v] + rem - 1];
			link[last] = now;
			if (!v) {
				v = newnode(n - rem + 1, inf, n - rem + 1 - depth[now]);
				last = now;
			}
			else if (x == c) {
				last = now;
				break;
			}
			else {
				int u = newnode(start[v], rem - 1, depth[now] + rem - 1);
				ch[u][x] = newnode(n, inf, n - depth[u]);
				ch[u][c] = v;
				start[v] += rem - 1;
				if (len[v] != inf)
					len[v] -= rem - 1;
				link[last] = v = u;
				last = v;
			}
		}
	}
	void maintain(int m) { //m为输入字符串的长度
	//对后缀树进行调整，并消除最后extend(sigma_size)对后缀树结构的影响。
	//调整后的后缀树的最后没有字符sigma_size，但是树边的长度可能为0，
	//并且遍历的时候要枚举所有的字符：0 <= c <= sigma_size
		ch[1][sigma_size] = 0;
		for (int i = 1; i <= cur; ++i) {
			if (len[i] == inf) {
				len[i] = m - start[i] + 1;
				pos[i] = depth[i];
				node[pos[i]] = i;
				depth[i] = m - depth[i] + 1;
			}
			else
				pos[i] = -1;
		}
	}
	void insert(const char* str) { //插入的字符串的下标从1开始
		assert(str[0] == 0);
		int m = strlen(str + 1);
		for (int i = 1; i <= m; ++i)
			extend(str[i] - 'a');
		extend(sigma_size);
		maintain(m);
	}
	int go(const char* str, int nd = 1) { //如果终止在边内则会到子结点
		int m = strlen(str);
		for (int i = 0; i < m; i += len[nd]) {
			int c = str[i] - 'a';
			if (!ch[nd][c])
				return 0;
			nd = ch[nd][c];
			for (int j = 0; j < len[nd] && i + j < m; ++j)
				if (str[i + j] - 'a' != s[start[nd] + j])
					return 0;
		}
		//如果有长度为0的边则直接走过去。在处理子树问题时应当直接返回nd。
		return ch[nd][sigma_size] != 0 ? ch[nd][sigma_size] : nd;
	}
public: //后缀树上倍增
	int L[maxn], R[maxn], dep[maxn], anc[maxn][maxlog]; //anc[i][j]表示结点i往上走2^j个点到达的点
	vector<int> seq;
	void dfs(int x, int fa) {
		dep[x] = dep[fa] + 1;
		anc[x][0] = fa;
		L[x] = seq.size();
		if (pos[x] > 0)
			seq.push_back(pos[x]);
		for (int i = 0; i <= sigma_size; ++i) if (ch[x][i])
			dfs(ch[x][i], x);
		R[x] = seq.size() - 1;
	}
	void preprocess() { //后缀树上倍增初始化
		for (int i = 1; i <= cur; ++i) {
			for (int j = 1; (1 << (j - 1)) <= cur; ++j)
				anc[i][j] = 0;
		}
		for (int j = 1; (1 << j) <= cur; ++j) {
			for (int i = 1; i <= cur; ++i) {
				if (anc[i][j - 1] != 0) {
					int a = anc[i][j - 1];
					anc[i][j] = anc[a][j - 1];
				}
			}
		}
	}
	void build() {		//求出后缀树的DFS序
		seq.clear();	//可以在此处向seq中加入一个元素0，从而使得DFS序区间从1开始
		dep[0] = -1;
		dfs(1, 0);		//求后缀树的DFS序
		preprocess();	//后缀树上倍增初始化
	}
	int ascend(int x, int length) { //将结点上升到加权深度为length的位置。
		for (int i = maxlog - 1; i >= 0; --i)
			if (depth[anc[x][i]] >= length) //调用该函数之前需要先调用preprocess初始化
				x = anc[x][i];
		return x;
	}
	int query(int L, int R) { //返回从根结点开始沿着字符串s[L, R]走到的结点（若最后结束在边上，则走到子结点）
		int x = node[L], length = R - L + 1;
		return ascend(x, length);
	}
	int lca(int x, int y) { //返回后缀树中结点x与y的最近公共祖先。
		if (dep[x] < dep[y])
			swap(x, y);
		for (int i = maxlog - 1; i >= 0; --i)
			if (dep[x] - (1 << i) >= dep[y])
				x = anc[x][i];
		if (x != y) {
			for (int i = maxlog - 1; i >= 0; --i)
				if (anc[x][i] && anc[x][i] != anc[y][i])
					x = anc[x][i], y = anc[y][i];
			x = anc[x][0];
		}
		return x;
	}
	int lcp(int i, int j) { //返回后缀s[i, m]与后缀s[j, m]的最长公共前缀。
		return depth[lca(node[i], node[j])];
	}
public: //后缀树上快速下降
	int sz[maxn], leaf[maxn];
	void travel(int x) { //调用travel(1)对后缀树进行树剖，之后才能调用go(x, L, R)。
		sz[x] = 1;
		leaf[x] = pos[x];
		for (int z = 0, i = 0; i <= sigma_size; ++i) {
			int y = ch[x][i];
			if (y) travel(y);
			sz[x] += sz[y];
			if (sz[y] > sz[z]) {
				z = y;
				leaf[x] = leaf[y];
			}
		}
	}
	int go(int x, int L, int R) { //从结点x开始往下走字符串s[L, R]，时间复杂度O(log^2n)
		while (x && L <= R) {
			if (s[L] == s[leaf[x] + depth[x]]) {
				int length = min(R - L + 1, lcp(leaf[x] + depth[x], L));
				L += length;
				int y = ascend(node[leaf[x]], depth[x] + length);
				if (L <= R && depth[y] != depth[x] + length)
					return 0;
				x = y;
			}
			else {
				int y = ch[x][s[L]];
				if (lcp(start[y], L) < min(len[y], R - L + 1))
					return 0;
				L += len[y];
				x = y;
			}
		}
		return x;
		//return ch[x][sigma_size] != 0 ? ch[x][sigma_size] : x;
	}
	int recognise(int l, int r, int L, int R) { //返回从根结点开始先走s[l, r]再走s[L, R]所到的结点。
		int x = query(l, r);
		int diff = depth[x] - (r - l + 1);
		if (diff > 0 && lcp(start[x] + len[x] - diff, L) < min(diff, R - L + 1))
			return 0;
		else
			return go(x, L + diff, R);
		//因为树中有长度为0的边，所以即使要识别的字符串为原串的后缀也不一定走到叶结点，
		//若要保证在这种情况下走到叶结点则应有：x = (ch[x][sigma_size] != 0 ? ch[x][sigma_size] : x);
	}
} st;

int main() {
	static char s[maxn];
	srand(time(0));
	int n = 200000;
	for (int i = 1; i <= n; ++i)
		s[i] = 'a' + (rand() % 2 == 0);
	auto start = clock();
	st.init();
	st.insert(s);
	st.build();
	st.travel(1);
	for (int i = 1; i <= n - 10; ++i) {
		int mid = (i + n) / 2;
		int x = st.recognise(i, mid, mid + 1, n);
		x = (st.ch[x][sigma_size] != 0 ? st.ch[x][sigma_size] : x);
		auto j = st.pos[x];
		if (j != i || st.depth[x] != n - i + 1) {
			printf("%d %d (%d)\n", j, i, x);
			abort();
		}
	}
	auto end = clock();
	printf("time: %f\n", double(end - start) / CLOCKS_PER_SEC);
	return 0;
}

﻿/*
在Trie树中建立后缀自动机：
只需DFS一遍Trie树，对于Trie中的当前结点u，它的父结点为p，p在后缀自动机中对应的结点为v。
则将v作为last，将u对应的字符插入后缀自动机中即可。（一定要先插入结点u，再插入结点u在Trie树中的子结点）
在建立广义后缀自动机时：
对于当前插入的字符串s，若s的前缀s[0, i]也是之前某个字符串的前缀，则在插入s[0, i]时，字符s[0]对应的结点出度为0，
而对于s[1, i]中的每个字符s[t]，它对应的结点在后缀自动机中入度为1，来源于s[t-1]。所以若从根结点开始走，不会走到这些结点，
故在后缀自动机中插入多个字符串不会破坏自动机的结构。同时对于s[0, i]中的每一个字符s[t]，它对应的结点虽然不可达，
但是会在parent树中出现，所以广义后缀自动机中记录的信息是完全的。
设在自动机中输入字符串str后到达结点u，并设u的right集合为R（一个结点right集合为其子结点right集合的并集），
则R记录了str在每个字符串中的所有的结束位置。
*/
//结论：从空串开始不断随机字符放到结尾直到s作为子串出现的期望次数=对s的所有border i计算f(i)的和，f(i)表示从头开始直接随机出i的概率的倒数
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <iostream>
#include <algorithm>
#include <vector>
#include <random>
#include <set>
#include <map>
using namespace std;
const int maxn = 210000; //maxn应当大于最大字符串长度的2倍
//后缀自动机的基本数据
int par[maxn], len[maxn], go[maxn][26]; //min[s] = len[par[s]] + 1，当前结点表示的最小长度等于父结点的最大长度加一
int cur, root, last;
//用于求parent树的DFS序
int first[maxn], nxt[maxn], info[maxn], id[maxn], L[maxn], R[maxn]; //right集合中的下标是子串**右**端点的位置
vector<int> seq;
//用于对后缀自动机进行拓扑排序
int cnt[maxn], arr[maxn];
int newstate(int length, int index = -1) {
	len[cur] = length;
	id[cur] = index;
	return cur++;
}
void init() {
	memset(go, 0, sizeof(go)); //如果数据组数很多，可能超时，应当改为memset(go, 0, sizeof(go[0]) * (2 * n + 10));
	cur = 1;
	root = last = newstate(0);
}
void extend(int w, int index) {
	int x = last;
	int nx = newstate(len[x] + 1, index);
	while (x && !go[x][w])
		go[x][w] = nx, x = par[x];
	if (!x)
		par[nx] = root;
	else {
		int y = go[x][w];
		if (len[x] + 1 == len[y])
			par[nx] = y;
		else {
			int ny = newstate(len[x] + 1);
			memcpy(go[ny], go[y], sizeof(go[y]));
			par[ny] = par[y];
			par[y] = ny;
			par[nx] = ny;
			while (x && go[x][w] == y)
				go[x][w] = ny, x = par[x];
		}
	}
	last = nx;
	//每加入一个新的字符，新产生的本质不同的子串个数为len[last] - len[par[last]]
}
set<int> travel(int x) { //采用按秩合并的方式处理得到结点x的right集合，最坏时间复杂度nlog^2n
	set<int> right;
	vector<set<int> > child;
	for (int i = first[x]; i != -1; i = nxt[i]) {
		child.push_back(travel(info[i]));
	}
	sort(child.begin(), child.end(), [](const auto& A, const auto& B) {
		return A.size() > B.size();
		});
	if (!child.empty())
		right = std::move(child[0]);
	for (int i = 1; i < child.size(); ++i)
		for (auto item : child[i])
			right.insert(item);
	if (id[x] != -1)
		right.insert(id[x]);
	//此处通过前面得到的right集合来计算答案，注意此处代码的时间复杂度不能达到O(n)，
	//否则总的时间复杂度可能会到O(n^2)甚至更高。
	return right;
}
void dfs(int x) {
	L[x] = seq.size();
	if (id[x] != -1)
		seq.push_back(id[x]);
	for (int i = first[x]; i != -1; i = nxt[i])
		dfs(info[i]);
	R[x] = seq.size() - 1;
}
void build() { //建树
	int sz = 0;
	seq.clear(); //可以在此处向seq中加入一个元素0，从而使得DFS序区间从1开始
	memset(first, -1, sizeof(first));
	for (int i = 1; i < cur; ++i) {
		int p = par[i];
		info[sz] = i;
		nxt[sz] = first[p];
		first[p] = sz++;
	}
	//travel(root); //遍历子树求解问题
	dfs(root); //求parent树的DFS序
}
void topsort() { //对后缀自动机进行拓扑排序
	for (int i = 1; i < cur; ++i)
		cnt[i] = 0;
	for (int i = 1; i < cur; ++i)
		cnt[len[i]]++;
	for (int i = 1; i < cur; ++i)
		cnt[i] += cnt[i - 1];
	for (int i = cur - 1; i >= 1; --i) //arr: [1, cur)
		arr[cnt[len[i]]--] = i;
	for (int i = 2; i < cur; ++i) //只有建立广义后缀自动机的时候才需要这个循环
		if (par[arr[i - 1]] == arr[i])
			swap(arr[i - 1], arr[i]);
	/*
		拓扑排序后从叶结点开始递推更新id数组，注意循环完成后id[0]为所有结点id的或。
		for (int i = cur - 1; i >= 1; --i) {
			int j = arr[i];
			if (id[par[j]] == -1)
				id[par[j]] = id[j];
			else
				id[par[j]] |= id[j];
		}
	*/
}
void insert(char* str, int id) { //通过多次调用insert函数向自动机中插入多个字符串，来建立广义后缀自动机。
	int n = strlen(str);
	last = root; //!!!
	for (int i = 0; i < n; ++i)
		extend(str[i] - 'a', id * 100 + i); //可以将第二个参数改为pair，来记录插入字符来源于的字符串编号和下标。
}
const int maxlog = 25;
int anc[maxn][maxlog]; //anc[i][j]表示结点i往上走2^j个点到达的点
map<int, int> trans; //id函数的反函数
void preprocess() { //parent树上倍增初始化
	trans.clear();
	for (int i = 1; i < cur; ++i)
		if (id[i] != -1)
			trans[id[i]] = i;
	for (int i = 1; i < cur; ++i) {
		anc[i][0] = par[i];
		for (int j = 1; (1 << (j - 1)) < cur; ++j)
			anc[i][j] = 0;
	}
	for (int j = 1; (1 << j) < cur; ++j) {
		for (int i = 1; i < cur; ++i) {
			if (anc[i][j - 1] != 0) {
				int a = anc[i][j - 1];
				anc[i][j] = anc[a][j - 1];
			}
		}
	}
}
int query(int id, int length) { //从标号id的结点往上走到len[p] >= length的深度最小的结点
	int p = trans[id];			//若要识别字符串的子串[L, R]，则调用query(id(R), R-L+1)，其中id(R)表示下标R对应的id
	for (int i = maxlog - 1; i >= 0; --i)
		if (len[anc[p][i]] >= length)
			p = anc[p][i];
	return p;
}
namespace Suffix_Tree { //建立反串的后缀树（后缀自动机的parent树是反串的后缀树）
	int pos[maxn]; //pos[x]表示结点x对应的字符串在原串中的结束下标。
	int ch[maxn][26]; //ch[x][w]表示结点x在后缀树中沿着字符w走到达的结点。
	char s[maxn];
	void extend(int w, int index) { //比之前的extend多了维护pos数组的代码。
		int x = last;
		int nx = newstate(len[x] + 1, index);
		pos[nx] = index;
		while (x && !go[x][w])
			go[x][w] = nx, x = par[x];
		if (!x)
			par[nx] = root;
		else {
			int y = go[x][w];
			if (len[x] + 1 == len[y])
				par[nx] = y;
			else {
				int ny = newstate(len[x] + 1);
				memcpy(go[ny], go[y], sizeof(go[y]));
				pos[ny] = pos[y];
				par[ny] = par[y];
				par[nx] = par[y] = ny;
				while (x && go[x][w] == y)
					go[x][w] = ny, x = par[x];
			}
		}
		last = nx;
	}
	void build(const char* str) { //对字符串str建立后缀自动机和反串的后缀树。
		strcpy(s, str);
		int n = strlen(s);
		last = root;
		for (int i = 0; i < n; ++i)
			extend(s[i] - 'a', i);
		for (int i = 2; i < cur; ++i) {
			int w = s[pos[i] - len[par[i]]] - 'a';
			ch[par[i]][w] = i;
		}
	}
	int walk(int x, int length, const char* str) { //从结点x开始沿着后缀树走字符串str，如果终止在边内则会到子结点。
		int m = strlen(str);
		for (int i = 0; i < m && i < len[x] - length; ++i)
			if (str[i] != s[pos[x] - length - i])
				return 0;
		for (int i = len[x] - length; i < m; i += len[x] - len[par[x]]) {
			int c = str[i] - 'a';
			if (!ch[x][c])
				return 0;
			x = ch[x][c];
			for (int j = 0; j < len[x] - len[par[x]] && i + j < m; ++j)
				if (str[i + j] != s[pos[x] - len[par[x]] - j])
					return 0;
		}
		return x;
	}
	int expand(int L, int R, const char* str) {
		int length = R - L + 1;
		int x = query(R, length);
		return walk(x, length, str);
	}
	/*
	建立的后缀树是后缀自动机的辅助数据结构，假设对字符串s建立后缀自动机，令结点x表示字符串s[L, R]，
	则go[x][c]表示字符串s[L, R] + c对应的结点，ch[x][c]表示字符串c + s[L, R]对应的结点。
	注意因为ch对应的边是后缀树中的边，边上是压缩的字符串而不是一个字符，所以连续向左扩展的时候应该
	调用walk函数或expand函数，而不是直接走ch。
	walk函数用字符串str向左扩展状态x，因为一个状态可能对应多个字符串，所以用length来明确指明字符串的长度，
	length应满足条件：len[par[x]] < length <= len[x]
	注意该函数会先扩展str[0]然后str[1]、str[2]...，最终结果是将str的反串拼接在x所表示的字符串的左边得到的结果。
	expand函数返回将str反向拼接在s[L, R]的左边所得到的状态。
	*/
}
namespace MultiString {
	//label[i]表示结点i的标记，times[i]记录结点i在多少个字符串中出现
	//real[i]表示结点i所能表示的最大长度（所有字符串在结点i所能表示的最大长度的最小值）
	int label[maxn], mx[maxn], times[maxn], real[maxn];
	void preprocess() { //初始化数据结构，要在match之前extend之后调用（必须在后缀自动机建立完成后调用）
		memset(label, -1, sizeof(label));
		memset(times, 0, sizeof(times));
		for (int i = 0; i <= cur; ++i)
			real[i] = len[i];
	}
	void match(const char* str, int index) {
		vector<pair<int, int>> nodes;
		int x = root, length = 0;
		for (const char* s = str; *s; ++s) {
			int c = *s - 'a';
			while (x != root && !go[x][c]) {
				x = par[x];
				length = len[x];
			}
			if (go[x][c]) {
				x = go[x][c];
				length += 1;
			}
			nodes.emplace_back(x, length);
		}
		sort(nodes.begin(), nodes.end(), [](auto a, auto b) {
			return len[a.first] > len[b.first];
		});
		vector<int> vec;
		for (auto pr : nodes) {
			int x = pr.first;
			while (x && label[x] != index) {
				vec.push_back(x);
				label[x] = index;
				mx[x] = 0;
				x = par[x];
			}
			mx[pr.first] = max(mx[pr.first], pr.second);
		}
		sort(vec.begin(), vec.end(), [](int a, int b) {
			return len[a] > len[b];
		});
		for (auto x : vec) {
			mx[par[x]] = max(mx[par[x]], len[par[x]]);
			real[x] = min(real[x], mx[x]);
			times[x] += 1;
		}
	}
	int longest_common_string(int n) {
		//设有n个字符串，任选一个构建后缀自动机，对其余的串调用match函数，
		//然后调用该函数，返回这些字符串的最长公共子串长度。
		int ans = 0;
		for (int i = 1; i < cur; ++i) if (times[i] == n - 1)
			ans = max(ans, real[i]);
		return ans;
	}
	long long number_of_common_string(int n) {
		//设有n个字符串，任选一个构建后缀自动机，对其余的串调用match函数，
		//然后调用该函数，返回这些字符串的本质不同的公共子串个数。
		long long ans = 0;
		for (int i = 1; i < cur; ++i) if (times[i] == n - 1)
			ans += max(0, real[i] - len[par[i]]);
		return ans;
	}
}
namespace Generalized_Suffix_Automaton { //广义后缀自动机
	//pos[i]表示结点i对应的子串在index==0的字符串中最左侧出现的下标
	//times[i]表示在parent树中结点i的子树中包含的类型数
	int par[maxn], len[maxn], go[maxn][26];
	int label[maxn], times[maxn];
	int n, cur, root, last, pos[maxn];
	int newstate(int length, int index = maxn) {
		len[cur] = length;
		pos[cur] = index;
		return cur++;
	}
	void init() { //n表示字符串的个数，需要在外部初始化
		memset(label, -1, sizeof(label));
		cur = 1;
		root = last = newstate(0);
	}
	void extend(int w, int index) {
		int x = last;
		int nx = newstate(len[x] + 1, index);
		while (x && !go[x][w])
			go[x][w] = nx, x = par[x];
		if (!x)
			par[nx] = root;
		else {
			int y = go[x][w];
			if (len[x] + 1 == len[y])
				par[nx] = y;
			else {
				int ny = newstate(len[x] + 1, pos[y]);
				memcpy(go[ny], go[y], sizeof(go[y]));
				times[ny] = times[y];
				par[ny] = par[y];
				par[y] = ny;
				par[nx] = ny;
				while (x && go[x][w] == y)
					go[x][w] = ny, x = par[x];
			}
		}
		last = nx;
	}
	//多次调用insert建立广义自动机，index从0开始
	void insert(const string& s, int index) {
		last = root;
		int pre = cur;
		for (int i = 0; i < s.size(); ++i)
			extend(s[i] - 'a', index == 0 ? i : maxn);
		for (int i = pre; i < cur; ++i) {
			for (int x = i; x && label[x] != index; x = par[x]) {
				label[x] = index;
				times[x] += 1;
				pos[par[x]] = min(pos[par[x]], pos[x]);
			}
		}
	}
	//dp[i]表示从结点i对应的任意字符串开始，能走到的本质不同的子串个数
	long long dp[maxn];
	long long dfs(int x) {
		if (dp[x] > 0)
			return dp[x];
		dp[x] = 0;
		for (int i = 0; i < 26; ++i) if (go[x][i] && times[go[x][i]] == n)
			dp[x] += dfs(go[x][i]) + 1;
		return dp[x];
	}
	void output(int x, long long k) { //输出第k小的本质不同公共子串
		if (k == 0) return;
		for (int i = 0; i < 26; ++i) if (go[x][i] && times[go[x][i]] == n) {
			if (k - dp[go[x][i]] - 1 > 0)
				k -= dp[go[x][i]] + 1;
			else {
				putchar('a' + i);
				output(go[x][i], k - 1);
				return;
			}
		}
	}
}
int main() {
	//freopen("in.txt", "r", stdin);
	static char s[maxn];
	init();
	scanf("%s", s);
	insert(s, 0);
	int n = 1;
	MultiString::preprocess();
	while (scanf("%s", s) == 1) 
		MultiString::match(s, ++n);
	printf("%d\n", MultiString::longest_common_string(n));
	return 0;
}

