const int maxn = 110000;
const int sigma_size = 26;
int info[maxn], ch[maxn][sigma_size], fail[maxn], len[maxn];
int cnt[maxn], num[maxn], par[maxn], node[maxn], last, cur, sz;
void init() {
	memset(ch, 0, sizeof(ch));
	memset(cnt, 0, sizeof(cnt));
	fail[0] = 1;
	info[0] = -1;
	len[1] = -1;
	cur = last = 1;
	sz = 0;
}
void extend(int w) {
	int p = last;
	info[++sz] = w;
	while (info[sz - len[p] - 1] != w)
		p = fail[p];
	if (!ch[p][w]) {
		int u = ++cur, x = fail[p];
		while (info[sz - len[x] - 1] != w)
			x = fail[x];
		par[u] = p;
		len[u] = len[p] + 2;
		fail[u] = ch[x][w]; //(*)
		ch[p][w] = u;
		num[u] = num[fail[u]] + 1;
	}
	last = ch[p][w];
	cnt[last]++;
}
void insert(char* str) { //输入字符串下标从0开始
	int n = strlen(str);
	for (int i = 0; i < n; ++i) {
		extend(str[i] - 'a');
		node[i] = last;
	}
}
void calc() {
	//更新fail的地方只有(*)处，此时将新建的结点u连接到之前的结点上而不改变之前的结点的连接状态，
	//这样，对于从cur到2的循环，就是对fail树按拓扑序逆序循环（也是对par树按拓扑序逆序循环）。
	for (int i = cur; i >= 2; --i)
		cnt[fail[i]] += cnt[i];
}
