	int p = node[index];		   //若要识别字符串的子串[L, R]，则调用query(L, R-L+1)
	for (int i = maxlog - 1; i >= 0; --i)
		if (len[anc[p][i]] >= length)
			p = anc[p][i];
	return p;
}

