﻿#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <cmath>
using namespace std;
void gcd(long long a, long long b, long long& d, long long& x, long long& y) {
	if (!b) {
		d = a;
		x = 1;
		y = 0;
	}
	else {
		gcd(b, a % b, d, y, x);
		y -= x * (a / b);
	}
}
int main() {
	//freopen("in.txt", "r", stdin);
	int T;
	scanf("%d", &T);
	while (T--) {
		long long a, b, c, g, x, y;
		scanf("%lld %lld %lld", &a, &b, &c);
		gcd(a, b, g, x, y);
		if (c % g != 0) { //ax + by = c 无解
			puts("-1");
			continue;
		}
		x = x * c / g, y = y * c / g; //算出一组特解
		long long dx = b / g, dy = a / g;
		//通解的形式为 (x + s * dx, y - s * dy)
		//若要求x和y都大于0，则s的取值范围为[L, R]
		long long L = x > 0 ? (1 - x) / dx : -x / dx + 1;
		long long R = y > 0 ? (y - 1) / dy : y / dy - 1;
		if (L <= R)
			printf("%lld %lld %lld %lld %lld\n", R - L + 1, x + L * dx, y - R * dy,
				x + R * dx, y - L * dy);
		else //无正整数数解时，分别输出x和y的最小正整数值
			printf("%lld %lld\n", x + L * dx, y - R * dy);
	}
	return 0;
}

#该程序展示了用15次多项式去拟合函数$f(x) = \int_0^xe^{-x^2}dx$
#这个积分是求不出来原函数的，但是我们可以将$e^{-x^2}$泰勒展开，然后再对得到的每个多项式积分就得到了一个和式：
#$\sum_{n=0}^{\infty}\frac{(-1)^nx^{2n+1}}{n!(2n+1)}$
#这个和式就是f(x)的泰勒展开式，我们用其前50项作为对f(x)的近似，并求出拟合函数。
from decimal import *
getcontext().prec = 100
maxn = 210
b = Decimal(1)
F = [0, 1]
for i in range(1, 50): #F为待求函数的泰勒展开式的系数，F[i]为x^i的系数，F中的项越多近似越好
    b *= -i
    F.append(0)
    F.append(1 / b / Decimal(2 * i + 1))
def asme(pos):
    length = pos + len(F) + 2
    t = [Decimal(0) for i in range(length)]
    for i in range(pos + 1):
        for j in range(len(F)):
            t[i + j] += a[pos][i] * F[j]
    res = Decimal(0)
    for i in range(length):
        res += t[i] * (pr[i + 1] - pl[i + 1]) / (i + 1)
    return res
L, R, T = Decimal(0), Decimal(2), 15 #待拟合区间为[L, R]，所用多项式的最高次数为T
a = [[Decimal(0) for j in range(maxn)] for i in range(maxn)]
c = [Decimal(0) for i in range(maxn)]
pl = [Decimal(1)]
pr = [Decimal(1)]
for i in range(maxn):
    pl.append(pl[-1] * L)
    pr.append(pr[-1] * R)
a[0][0] = 1 / (R - L).sqrt()
for i in range(1, T + 1):
    a[i][i] = Decimal(1)
    for j in range(i):
        sum = Decimal(0)
        for k in range(j + 1):
            sum += a[j][k] * (pr[i + k + 1] - pl[i + k + 1]) / (i + k + 1)
        for k in range(j + 1):
            a[i][k] -= sum * a[j][k]
    total = Decimal(0)
    for j in range(i + 1):
        for k in range(i + 1):
            total += a[i][j] * a[i][k] * (pr[j + k + 1] - pl[j + k + 1]) / (j + k + 1)
    length = total.sqrt()
    for j in range(i + 1):
        a[i][j] /= length
for pos in range(T + 1):
	res = asme(pos);
	for i in range(pos + 1):
		c[i] += a[pos][i] * res;
for i in range(T + 1):
    print("%.20e" % c[i], end=", ")

﻿#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <cmath>
#include <numeric>
using namespace std;
const int maxn = 110;
const long double pi = acos(-1.0L);
const long double L = -pi, R = pi; //函数f(x)的定义域为[L, R]
const int T = 15; //用不超过T次的多项式对函数f(x)进行拟合
long double a[maxn][maxn]; //a[i]表示第i个规范正交基，a[i][j]表示第i个基的x^j的系数
long double pl[maxn], pr[maxn]; //pl[i] = pow(L, i), pr[i] = pow(R, i)
long double c[maxn]; //拟合出来的多项式系数
int pos = 0;
long double f(long double x) { //待拟合函数
	return sin(x);
}
long double calc(long double x) {
	long double result = 0, y = 1;
	for (int i = 0; i <= pos; ++i) {
		result += a[pos][i] * y;
		y *= x;
	}
	return result * f(x);
}
long double simpson(long double l, long double r) { //计算函数calc在区间[l, r]上的辛普森积分
	return (calc(l) + calc(r) + 4 * calc((l + r) / 2)) * (r - l) / 6;
}
long double solve(long double l, long double r, long double eps, long double val) { //递归求解积分
	long double mid = (l + r) / 2;
	long double L = simpson(l, mid), R = simpson(mid, r);
	if (fabs(L + R - val) <= 15 * eps)
		return L + R + (L + R - val) / 15;
	return solve(l, mid, eps / 2, L) + solve(mid, r, eps / 2, R);
}
//eps设置太小可能会导致死循环
long double asme(long double l, long double r, long double eps = 1e-16l) { //自适应辛普森积分
	return solve(l, r, eps, simpson(l, r));	//求函数calc在区间[l, r]上的自适应辛普森积分，eps指定精度
}
int main() {
	pl[0] = pr[0] = 1;
	for (int i = 1; i < maxn; ++i) {
		pl[i] = pl[i - 1] * L;
		pr[i] = pr[i - 1] * R;
	}
	a[0][0] = 1 / sqrt(R - L);
	for (int i = 1; i <= T; ++i) { //计算第i个规范正交基
		a[i][i] = 1;
		for (int j = 0; j < i; ++j) {
			long double sum = 0; //sum = <x^i, a[j]>
			for (int k = 0; k <= j; ++k)
				sum += a[j][k] * (pr[i + k + 1] - pl[i + k + 1]) / (i + k + 1);
			for (int k = 0; k <= j; ++k)
				a[i][k] -= sum * a[j][k];
		}
		long double total = 0;
		for (int j = 0; j <= i; ++j)
			for (int k = 0; k <= i; ++k)
				total += a[i][j] * a[i][k] * (pr[j + k + 1] - pl[j + k + 1]) / (j + k + 1);
		long double length = sqrt(total);
		for (int j = 0; j <= i; ++j)
			a[i][j] /= length;
	}
	for (::pos = 0; pos <= T; ++pos) {
		long double res = asme(L, R);
		for (int i = 0; i <= pos; ++i)
			c[i] += a[pos][i] * res;
	}
	for (int i = 0; i <= T; ++i)
		printf("%.17le,", c[i]);
	return 0;
}

﻿#include <cstdio>
