        scanf("%lf", &a[i]);
    for (int i = 0; i <= m; ++i)
        scanf("%lf", &b[i]);
    auto ans = a * b;
    for (int i = 0; i < ans.size(); ++i)
        printf("%.0f ", ans[i] + 1e-8);
    return 0;
}

