}
matrix pow_sum(matrix A, int m) //pow_sum(A, m) = sigma pow(A, i)
{                               //               1<=i<=m
	matrix ans, B = A;
	while (m)
	{
		if (m & 1)
			ans = ans * A + B;
		B = B * A + B;
		A = A * A;
		m >>= 1;
	}
	return ans;
}
long long pow_sum(long long a, int m) //pow_sum(A, m) = sigma pow(A, i)
{                               //                      1<=i<=m
	long long ans = 0, b = a;
	while (m)
	{
		if (m & 1)
			ans = (ans * a + b) % mod;
		b = (b * a + b) % mod;
		a = (a * a) % mod;
		m >>= 1;
	}
	return ans;
}
