			printf("1\n");
			continue;
		}
		if (n == -1) {
			printf("%d\n", 2 * pow_mod(k + 1, mod - 2) % mod);
			continue;
		}
		int rev = pow_mod(k, mod - 2);
		for (int i = 0; i < k; ++i)
			c[i] = rev;
		a[0] = 1;
		for (int i = 1; i < k; ++i) {
			for (int j = i - k; j < i; ++j) if (j >= 0) {
				a[i] += 1ll * rev * a[j] % mod;
				if (a[i] >= mod)a[i] -= mod;
			}
		}
