﻿/*
用雅可比方法求出实对称矩阵的特征值和特征向量，注意必须是实对称矩阵。
时间复杂度O(n^3)，大常数。
*/
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <vector>
#include <array>
#include <cmath>
using namespace std;
const int maxn = 210;
const double eps = 1e-8;
using matrix = double[maxn][maxn];
using vec = array<double, maxn>;
using pair_t = pair<double, vec>;
struct {
	matrix A, V;
	int column[maxn], n;
	void update(int r, int c, double v) {
		A[r][c] = v;
		if (column[r] == c || fabs(A[r][c]) > fabs(A[r][column[r]])) {
			for (int i = 0; i < n; ++i) if (i != r)
				if (fabs(A[r][i]) > fabs(A[r][column[r]]))
					column[r] = i;
		}
	}
	void Jacobi() {
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j)
				V[i][j] = 0;
			V[i][i] = 1;
			column[i] = (i == 0 ? 1 : 0);
		}
		for (int i = 0; i < n; ++i)
			for (int j = 0; j < n; ++j)
				if (j != i && fabs(A[i][j]) > fabs(A[i][column[i]]))
					column[i] = j;
		for (int T = 0; ; ++T) { //迭代次数限制
			int x, y;
			double val = 0;
			for (int i = 0; i < n; ++i)
				if (fabs(A[i][column[i]]) > val)
					val = fabs(A[i][column[i]]), x = i, y = column[i];
			if (val < eps) //精度限制
				break;
			double phi = atan2(-2 * A[x][y], A[y][y] - A[x][x]) / 2;
			double sinp = sin(phi), cosp = cos(phi);
			for (int i = 0; i < n; ++i) if (i != x && i != y) {
				double a = A[x][i] * cosp + A[y][i] * sinp;
				double b = A[x][i] * -sinp + A[y][i] * cosp;
				update(x, i, a);
				update(y, i, b);
			}
			for (int i = 0; i < n; ++i) if (i != x && i != y) {
				double a = A[i][x] * cosp + A[i][y] * sinp;
				double b = A[i][x] * -sinp + A[i][y] * cosp;
				update(i, x, a);
				update(i, y, b);
			}
			for (int i = 0; i < n; ++i) {
				double a = V[i][x] * cosp + V[i][y] * sinp;
				double b = V[i][x] * -sinp + V[i][y] * cosp;
				V[i][x] = a, V[i][y] = b;
			}
			double a = A[x][x] * cosp * cosp + A[y][y] * sinp * sinp + 2 * A[x][y] * cosp * sinp;
			double b = A[x][x] * sinp * sinp + A[y][y] * cosp * cosp - 2 * A[x][y] * cosp * sinp;
			double tmp = (A[y][y] - A[x][x]) * sin(2 * phi) / 2 + A[x][y] * cos(2 * phi);
			update(x, y, tmp);
			update(y, x, tmp);
			A[x][x] = a, A[y][y] = b;
		}
	}
	//返回特征值和特征向量组成的pair，按照特征值从大到小排序
	auto solve(const matrix& input, int n) {
		this->n = n;
		for (int i = 0; i < n; ++i)
			for (int j = 0; j < n; ++j)
				A[i][j] = input[i][j];
		Jacobi();
		vector<pair_t> result;
		for (int i = 0; i < n; ++i)
			result.emplace_back(A[i][i], vec());
		for (int i = 0; i < n; ++i)
			for (int j = 0; j < n; ++j)
				result[i].second[j] = V[j][i];
		sort(result.begin(), result.end(), greater<pair_t>());
		return result;
	}
}jacobi;
matrix tmp = { {15.980000, 3.400000, -10.370000, },
	{3.400000, 8.492000, -8.062000, },
	{-10.370000, -8.062000, 11.572000, }, };
int main() {
	auto result = jacobi.solve(tmp, 3);
	for (int i = 0; i < 3; ++i) {
		auto eigenvalue = result[i].first;
		auto eigenvector = result[i].second;
		printf("(%f)", eigenvalue);
		for (int i = 0; i < 3; ++i)
			printf(" %f", eigenvector[i]);
		printf("\n");
	}
	return 0;
}

﻿#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <vector>
#include <array>
using namespace std;
const int maxn = 100;
using matrix = double[maxn][maxn];
using vect = array<double, maxn>;
//当方程有唯一解的时候，算出唯一解
//矩阵A的大小为n * (n + 1)
void gauss_elimination(matrix A, int n) {
	for (int i = 0; i < n; ++i) {
		int r = i;
		for (int j = i + 1; j < n; ++j)
			if (fabs(A[j][i]) > fabs(A[r][i]))
				r = j;
		if (r != i) for (int j = 0; j <= n; ++j)
			swap(A[r][j], A[i][j]);
		for (int k = i + 1; k < n; ++k)
			for (int j = n; j >= i; --j)
				A[k][j] -= A[k][i] / A[i][i] * A[i][j];
	}
	for (int i = n - 1; i >= 0; --i) {
		for (int j = i + 1; j < n; ++j)
			A[i][n] -= A[j][n] * A[i][j];
		A[i][n] /= A[i][i];
	}
}
//无解返回-1，有唯一解返回0，有无穷多解返回1。
//在有解的情况下通过ans返回任意一个解。
//矩阵A的大小为n * (m + 1)，表示有n个方程，m个变量。
const double eps = 1e-8;
int row[maxn], var[maxn];
int one_possible(matrix A, int n, int m, vect& ans) {
	memset(row, -1, sizeof(row));
	int r = 0;
	for (int c = 0; c < m && r < n; ++c) {
		int x = r;
		for (int i = x + 1; i < n; ++i)
			if (fabs(A[i][c]) > fabs(A[x][c]))
				x = i;
		if (x != r) for (int j = 0; j <= m; ++j)
			swap(A[x][j], A[r][j]);
		if (fabs(A[r][c]) < eps)
			continue;
		for (int k = r + 1; k < n; ++k)
			for (int j = m; j >= c; --j)
				A[k][j] -= A[k][c] / A[r][c] * A[r][j];
		row[c] = r++;
	}
	for (int i = r; i < n; ++i) if (fabs(A[i][m]) > eps)
		return -1;
	for (int c = m - 1; c >= 0; --c) {
		int x = row[c];
		if (x < 0)
			ans[c] = 0;
		else {
			for (int i = x - 1; i >= 0; --i)
				A[i][m] -= A[i][c] / A[x][c] * A[x][m];
			ans[c] = A[x][m] / A[x][c];
		}
	}
	return r < m;
}
//计算方程的最小二乘解
void least_square(matrix A, int n, int m, vect& ans) {
	static matrix T;
	for (int i = 0; i < n; ++i)
		for (int j = 0; j <= m; ++j)
			T[i][j] = A[i][j];
	for (int i = 0; i < m; ++i) {
		for (int j = 0; j <= m; ++j) {
			A[i][j] = 0;
			for (int k = 0; k < n; ++k)
				A[i][j] += T[k][i] * T[k][j];
		}
	}
	one_possible(A, m, m, ans);
}
//将矩阵A化为简化阶梯形
//ans为方程组的一个特解，basis为齐次方程组解空间的一组基。
//该算法针对稀疏矩阵进行了优化，在矩阵中有大量0元素时，时间复杂度会小于O(n^3)。
int row_simplify(matrix A, int n, int m, vect& ans, vector<vect>& basis) {
	memset(row, -1, sizeof(row));
	int r = 0;
	for (int c = 0; c < m && r < n; ++c) {
		int x = r;
		for (int i = x + 1; i < n; ++i)
			if (fabs(A[i][c]) > fabs(A[x][c]))
				x = i;
		if (x != r) for (int j = 0; j <= m; ++j)
			swap(A[x][j], A[r][j]);
		if (fabs(A[r][c]) < eps)
			continue;
		for (int j = m; j >= c; --j)
			A[r][j] /= A[r][c];
		for (int k = r + 1; k < n; ++k) if (fabs(A[k][c]) > eps)
			for (int j = m; j >= c; --j)
				A[k][j] -= A[k][c] * A[r][j];
		var[r] = c;
		row[c] = r++;
	}
	for (int i = r; i < n; ++i) if (fabs(A[i][m]) > eps)
		return -1;
	for (int c = m - 1; c >= 0; --c) {
		int x = row[c];
		if (x < 0)
			ans[c] = 0;
		else {
			for (int i = x - 1; i >= 0; --i) if (fabs(A[i][c]) > eps)
				for (int j = m; j >= c; --j)
					A[i][j] -= A[i][c] * A[x][j];
			ans[c] = A[x][m];
		}
	}
	//求出基础解系
	for (int c = m - 1; c >= 0; --c) if (row[c] < 0) {
		vect now = {};
		for (int i = 0; i < r; ++i)
			now[var[i]] = -A[i][c];
		now[c] = 1;
		basis.push_back(now);
	}
	return r < m;
}
namespace rectangle_mod {
	const int mod = 998244353;
