				swap(A[r][j], A[i][j]);
			int pivot = inv(A[i][i]);
			for (int k = i + 1; k < n; ++k) {
				int val = 1LL * A[k][i] * pivot % mod;
				for (int j = m - 1; j >= i; --j)
					A[k][j] = (A[k][j] - 1LL * A[i][j] * val % mod + mod) % mod;
			}
		}
		for (int i = n - 1; i >= 0; --i) {
			for (int j = i + 1; j < n; ++j) {
				for (int k = n; k < m; ++k)
					A[i][k] = (A[i][k] - 1LL * A[j][k] * A[i][j] % mod + mod) % mod;
			}
			int pivot = inv(A[i][i]);
			for (int k = n; k < m; ++k)
				A[i][k] = 1LL * A[i][k] * pivot % mod;
		}
	}
}
