}
void pushdown(node* x) {
	if (x->rev) {
		x->rev = 0;
		if (x->ch[0] != nil) x->ch[0]->rev ^= 1;
		if (x->ch[1] != nil) x->ch[1]->rev ^= 1;
		swap(x->ch[0], x->ch[1]);
	}
	if (x->add) {
		if (x->ch[0] != nil)
			increase(x->ch[0], x->add);
		if (x->ch[1] != nil)
			increase(x->ch[1], x->add);
		x->add = 0;
	}
}
void rotate(node* x, int d) {
	if (isroot(x)) return;
	node* y = x->p;
	y->ch[!d] = x->ch[d];
	x->ch[d]->p = y;
	x->p = y->p;
	if (!isroot(y))
		y->p->ch[y == y->p->ch[1]] = x;
	x->ch[d] = y;
	y->p = x;
	pushup(y);
}
void splay(node* x) { //若要修改一个点的权值则要先将其伸展到根
	static node* sta[maxn];
	int top = 1;
	sta[0] = x;
	for (node* y = x; !isroot(y); y = y->p)
		sta[top++] = y->p;
	while (top) pushdown(sta[--top]);
	while (!isroot(x)) {
		node* y = x->p;
		if (isroot(y))
			rotate(x, x == y->ch[0]);
		else {
			int d = y == y->p->ch[0];
			if (x == y->ch[d])
				rotate(x, !d);
			else
				rotate(y, d);
			rotate(x, d);
		}
	}
	pushup(x);
}
