    inline void node::up() {
        s = lch->s + rch->s + 1;
        sum = lch->sum + rch->sum + val;
    }
    inline void node::down() {
        if (add) {
            if (lch.ptr != nil) {
                lch = copy(lch.ptr);
                lch->mark(add);
            }
            if (rch.ptr != nil) {
                rch = copy(rch.ptr);
                rch->mark(add);
            }
            add = 0;
        }
    }
}
