#include <vector>
#define lc t[p].lchild
#define rc t[p].rchild
template<typename T, int begin, int end, int factor = 30>
struct Array {
	static const int size = end - begin + 1;
	struct segment {
		int lchild, rchild;
		T val;
	}t[size * factor];
	int sz;
	void ins(int& p, int x, int y, T A[]) {
		p = ++sz;
		if (x == y) 
			t[p].val = A[x];
		else {
			int mid = (x + y) >> 1;
			ins(lc, x, mid, A);
			ins(rc, mid + 1, y, A);
		}
	}
	//将数组A中的值作为初始值，并返回初始数组的版本号
	int init(T A[]) {
		int root = sz = 0;
		ins(root, begin, end, A);
		return root;
	}
	//将val作为可持久化数组的初始值，并返回初始数组的版本号（0）
	//采用此初始化方案时，数组的区间范围可以很大，
	//且可以在get函数中加入p==0就直接返回t[0].val的优化
	int init(T val) {
		t[0].val = val;
		return 0;
	}
	//获取版本号p的下标为index的值
	T get(int p, int index, int x = begin, int y = end) {
		if (x == y)
			return t[p].val;
		int mid = (x + y) >> 1;
		if (index <= mid)
			return get(lc, index, x, mid);
		else
			return get(rc, index, mid + 1, y);
	}
	//修改版本号为p的数组的下标index位置的值为v
	//使用方法为：root[i] = root[i-1]; set(root[i], idx, v);
	void set(int &p, int index, const T& v, int x = begin, int y = end) {
		t[++sz] = t[p]; p = sz; //如果类型T的复制开销较大，此处可以考虑只复制左右子树的编号
		if (x == y) 
			t[p].val = v;
		else {
			int mid = (x + y) >> 1;
			if (index <= mid)
				set(lc, index, v, x, mid);
			else
				set(rc, index, v, mid + 1, y);
		}
	}
};

const int maxn = 1000;
Array<int, 0, maxn, 100> arr;
int A[maxn];
int main() {
	using namespace std;
	for (int i = 0; i < maxn; ++i)
		A[i] = -1;
	int p = arr.init(-1);
	for (int i = 0; i < maxn; ++i)
		if (arr.get(p, i) != A[i])
			abort();
	vector<int> total[maxn];
	vector<int> root; root.push_back(p);
	total[0] = vector<int>(A, A + maxn);
	int T = 10000;
	while (T--) {
		int tp = rand() % 10;
		int pos = rand() % maxn, nd = rand() % root.size();
		int value = rand();
		if (tp != 0) {
			if (arr.get(root[nd], pos) != total[nd][pos]) {
				abort();
			}
		}
		else {
			int sz = root.size();
			total[sz] = total[nd];
			total[sz][pos] = value;
			root.push_back(root[nd]);
			arr.set(root.back(), pos, value);
		}
	}
	return 0;
}

﻿#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <iostream>
#include <algorithm>
#include <random>
#include <vector>
#include <ctime>
#include <iterator>
using namespace std;
const int inf = 1 << 30;
static const int maxn = 210000; //maxn应当大于所有集合大小的总和
struct node {		//该算法实现的整数集合为可重集合（multiset）
	int l, r, v;	//左节点编号 右节点编号 值
} T[maxn * 25];
int len, sz, info[maxn]; //len是值域线段树的长度
int ranking(int v) {
	//如果不需要数据离散化直接return v即可，同时还要将所有的info[v]改为v，此时线段树的值域为[1, len]。
	return lower_bound(info + 1, info + len + 1, v) - info;
}
void ins(int& i, int l, int r, int p) { //在区间[l, r]中插入p 
	T[++sz] = T[i]; i = sz;
	T[i].v++; //递增当前区间内值的个数 
	if (l == r) return;
	int m = (l + r) / 2;
	if (p <= m) ins(T[i].l, l, m, p);
	else ins(T[i].r, m + 1, r, p);
}
int insert(int x, int v) { //向集合x中添加数值v，返回新的集合的编号，原来的集合不会改变
	ins(x, 1, len, ranking(v));
	return x;
}
void init(int* A, int length) { //输入数组A的下标从1开始，length表示A的长度
	sz = 0;						//A记录集合中所有可能出现的整数
	copy(A + 1, A + length + 1, info + 1);
	sort(info + 1, info + length + 1); //如果没有离散化需要对len进行赋值来指明线段树的值域。
	len = unique(info + 1, info + length + 1) - info - 1; //对info数组进行排序去重
}
int kth(int x, int k) { //查找集合x中的第k大元素
	int l = 1, r = len;
	while (l < r) {
		int m = (l + r) / 2, t = T[T[x].l].v;
		if (k <= t)
			x = T[x].l, r = m;
		else
			x = T[x].r, l = m + 1, k -= t;
	}
	if (k > T[x].v) //如果k大于集合x的大小，则返回inf
		return inf;
	return info[r];
}
int ask(int x, int v) { //返回集合x中比v小的数的个数
	int l = 1, r = len, k = 0;
	int p = ranking(v) - 1;
	if (p <= 0) return 0;
	while (l < r) {
		int m = (l + r) / 2, t = T[T[x].l].v;
		if (p <= m)
			x = T[x].l, r = m;
		else
			x = T[x].r, l = m + 1, k += t;
	}
	k += T[x].v;
	return k;
}
int pre(int x, int v) { //在集合x中查询v的前驱，找不到返回-inf
	int k = ask(x, v);
	if (k == 0) return -inf;
	return kth(x, k);
}
int next(int x, int v) { //在集合x中查询v的后继，找不到返回inf
	int k = ask(x, v + 1) + 1;
	return kth(x, k);
}
int count(int x, int v) { //返回集合x中数值v的个数
	int l = 1, r = len;
	int p = ranking(v);
	if (p > len || info[p] != v)
		return 0;
	while (l < r && T[x].v> 0) {
		int m = (l + r) / 2;
		if (p <= m)
			x = T[x].l, r = m;
		else
			x = T[x].r, l = m + 1;
	}
	return T[x].v;
}
bool find(int x, int v) { //返回集合x中是否存在v
	return count(x, v) >= 1;
}
int maximum(int x) { //返回集合x中的最大值
	int l = 1, r = len;
	if (T[x].v == 0) //如果集合为空则返回-inf
		return -inf;
	while (l < r) {
		int m = (l + r) / 2, t = T[T[x].r].v;
		if (t == 0)
			x = T[x].l, r = m;
		else
			x = T[x].r, l = m + 1;
	}
	return info[r];
}
int minimum(int x) { //返回集合x中的最小值
	int l = 1, r = len;
	if (T[x].v == 0) //如果集合为空则返回inf
		return inf;
	while (l < r) {
		int m = (l + r) / 2, t = T[T[x].l].v;
		if (t > 0)
			x = T[x].l, r = m;
		else
			x = T[x].r, l = m + 1;
	}
	return info[r];
}
int merge(int x, int y, int l = 1, int r = len) {	//将集合x与集合y合并成一个新的集合后返回
	if (!x) return y;								//不会改变x和y
	if (!y) return x;
	int i = ++sz;
	if (l == r) {
		T[i].v = T[x].v + T[y].v;
		T[i].l = T[i].r = 0;
	}
	else {
		int m = (l + r) / 2;
		T[i].l = merge(T[x].l, T[y].l, l, m);
		T[i].r = merge(T[x].r, T[y].r, m + 1, r);
		T[i].v = T[T[i].l].v + T[T[i].r].v;
	}
	return i;
}
int diff(int x, int y, int l = 1, int r = len) {	//返回集合x与集合y的差集（x - y），不会改变x和y
	int i = ++sz; T[i] = T[x];						//时间复杂度size(y)log(len)
	if (l == r) {
		T[i].v = max(0, T[x].v - T[y].v);
	}
	else {
		int m = (l + r) / 2;
		if (T[y].l)
			T[i].l = diff(T[x].l, T[y].l, l, m);
		if (T[y].r)
			T[i].r = diff(T[x].r, T[y].r, m + 1, r);
		T[i].v = T[T[i].l].v + T[T[i].r].v;
	}
	return i;
}
int intersect(int x, int y, int l = 1, int r = len) {	//返回集合x与集合y的交集（不会改变x和y）
	int i = ++sz;										//时间复杂度min{size(x),size(y)} * log(len)
	if (l == r) {
		T[i].v = min(T[x].v, T[y].v);
		T[i].l = T[i].r = 0;
	}
	else {
		int m = (l + r) / 2;
		T[i].l = (!T[x].l || !T[y].l ? 0 : intersect(T[x].l, T[y].l, l, m));
		T[i].r = (!T[x].r || !T[y].r ? 0 : intersect(T[x].r, T[y].r, m + 1, r));
		T[i].v = T[T[i].l].v + T[T[i].r].v;
	}
	return T[i].v == 0 ? 0 : i;
}
int symmetric(int x, int y, int l = 1, int r = len) {	//返回集合x与集合y的对称差分（不会改变x和y）						
	if (!x) return y;									//时间复杂度min{size(x),size(y)} * log(len)
	if (!y) return x;
	int i = ++sz;
	if (l == r) {
		T[i].v = abs(T[x].v - T[y].v);
		T[i].l = T[i].r = 0;
	}
	else {
		int m = (l + r) / 2;
		T[i].l = symmetric(T[x].l, T[y].l, l, m);
		T[i].r = symmetric(T[x].r, T[y].r, m + 1, r);
		T[i].v = T[T[i].l].v + T[T[i].r].v;
	}
	return i;
}
void left(vector<int>& X, vector<int>& Y) {
	for (auto& i : X)
		i = T[i].l;
	for (auto& i : Y)
		i = T[i].l;
}
void right(vector<int>& X, vector<int>& Y) {
	for (auto& i : X)
		i = T[i].r;
	for (auto& i : Y)
		i = T[i].r;
}
int left_value(vector<int>& X, vector<int>& Y) {
	int tot = 0;
	for (auto i : X)
		tot += T[T[i].l].v;
	for (auto i : Y)
		tot -= T[T[i].l].v;
	return tot;
}
int right_value(vector<int>& X, vector<int>& Y) {
	int tot = 0;
	for (auto i : X)
		tot += T[T[i].r].v;
	for (auto i : Y)
		tot -= T[T[i].r].v;
	return tot;
}
int value(vector<int>& X, vector<int>& Y) {
	int tot = 0;
	for (auto i : X)
		tot += T[i].v;
	for (auto i : Y)
		tot -= T[i].v;
	return tot;
}
int kth(vector<int> X, vector<int> Y, int k) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合的第k大
	int l = 1, r = len;							//必须保证Y的并集 是 X的并集 的子集
	while (l < r) {
		int m = (l + r) / 2, t = left_value(X, Y);
		if (k <= t)
			left(X, Y), r = m;
		else
			right(X, Y), l = m + 1, k -= t;
	}
	if (k > value(X, Y))
		return inf;
	return info[r];
}
int ask(vector<int> X, vector<int> Y, int v) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合中比v小的数的个数
	int l = 1, r = len, k = 0;					//必须保证Y的并集 是 X的并集 的子集
	int p = ranking(v) - 1;
	if (p <= 0) return 0;
	while (l < r) {
		int m = (l + r) / 2;
		if (p <= m)
			left(X, Y), r = m;
		else {
			k += left_value(X, Y);
			right(X, Y);
			l = m + 1;
		}
	}
	k += value(X, Y);
	return k;
}
int pre(vector<int> X, vector<int> Y, int v) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合中v的前驱
	int k = ask(X, Y, v);						//必须保证Y的并集 是 X的并集 的子集
	if (k == 0) return -inf; //找不到返回-inf
	return kth(X, Y, k);
}
int next(vector<int> X, vector<int> Y, int v) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合中v的后继
	int k = ask(X, Y, v + 1) + 1;				//必须保证Y的并集 是 X的并集 的子集
	return kth(X, Y, k); //找不到返回inf
}
int count(vector<int> X, vector<int> Y, int v) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合中v的个数
	int l = 1, r = len;								//必须保证Y的并集 是 X的并集 的子集
	int p = ranking(v);
	if (p > len || info[p] != v)
		return 0;
	while (l < r) {
		int m = (l + r) / 2;
		if (p <= m)
			left(X, Y), r = m;
		else
			right(X, Y), l = m + 1;
	}
	return value(X, Y);
}
int maximum(vector<int> X, vector<int> Y) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合中的最大值
	int l = 1, r = len;						//必须保证Y的并集 是 X的并集 的子集
	if (value(X, Y) == 0) //如果集合为空则返回-inf
		return -inf;
	while (l < r) {
		int m = (l + r) / 2, t = right_value(X, Y);
		if (t == 0)
			left(X, Y), r = m;
		else
			right(X, Y), l = m + 1;
	}
	return info[r];
}
int minimum(vector<int> X, vector<int> Y) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合中的最小值
	int l = 1, r = len;						//必须保证Y的并集 是 X的并集 的子集
	if (value(X, Y) == 0) //如果集合为空则返回inf
		return inf;
	while (l < r) {
		int m = (l + r) / 2, t = left_value(X, Y);
		if (t > 0)
			left(X, Y), r = m;
		else
			right(X, Y), l = m + 1;
	}
	return info[r];
}

#define VALUE_TYPE 5000
int tmp[maxn], root[maxn];
vector<int> A[maxn];
int main() {
	int n = 10, q = 400000;
	default_random_engine e;
	uniform_int_distribution<int> d(1, VALUE_TYPE);
	uniform_int_distribution<int> big(-100000000, 100000000);
	//e.seed(time(0));
	for (int i = 1; i <= VALUE_TYPE; ++i)
		tmp[i] = big(e);
	init(tmp, VALUE_TYPE);
	int rt = 0;
	vector<int> vec;
	for (int i = 1; i <= 100000; ++i) {
		int val = d(e); val = tmp[val];
		if (rand() % 2)
			root[0] = insert(root[0], val), A[0].push_back(val);
		else
			root[1] = insert(root[1], val), A[1].push_back(val);
	}
	rt = symmetric(root[0], root[1]);
	sort(A[0].begin(), A[0].end());
	sort(A[1].begin(), A[1].end());
	std::set_symmetric_difference(A[0].begin(), A[0].end(), A[1].begin(), A[1].end(), back_inserter(vec));
	//rt = root[1]; vec = A[1];
	vec.push_back(-inf); vec.push_back(inf);
	sort(vec.begin(), vec.end());
	printf("%d %d\n", vec.size(), T[rt].v);
	for (int q = 0; q < 100000; ++q) {
		if (q % 1000 == 0) printf("%d\n", q);
		int tp = rand() % 8, val = d(e);
		val = tmp[val];
		if (tp == 0) {
			rt = insert(rt, val);
			vec.push_back(val);
			sort(vec.begin(), vec.end());
		}
		else if (tp == 1) {
			int k = rand() % T[rt].v + 1;
			if (vec[k] != kth(rt, k))
				abort();
		}
		else if (tp == 2) {
			if (lower_bound(vec.begin(), vec.end(), val) - vec.begin() - 1 != ask(rt, val))
				abort();
		}
		else if (tp == 3) {
			int p = lower_bound(vec.begin(), vec.end(), val) - vec.begin() - 1;
			if (vec[p] != pre(rt, val))
				abort();
		}
		else if (tp == 4) {
			int p = upper_bound(vec.begin(), vec.end(), val) - vec.begin();
			if (vec[p] != next(rt, val))
				abort();
		}
		else if (tp == 5) {
			if (count(rt, val) != count(vec.begin(), vec.end(), val))
				abort();
		}
		else if (tp == 6) {
			if (*-- --vec.end() != maximum(rt))
				abort();
		}
		else if (tp == 7) {
			if (*++vec.begin() != minimum(rt))
				abort();
		}
	}
	return 0;
}

﻿/*
可持久化线段树：区间取min
每次update之后返回新版本的线段树的根结点。
查询操作传入相应版本的线段树的根结点即可。
因为要可持久化，所以必须标记永久化，不能pushdown。
*/
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
using namespace std;
const int maxn = 110000;
const int inf = 1 << 30;
struct node {
	int l, r, lc, rc;
	int minv, tag;
} t[maxn * 20];
int cur = 0, mn;
void init() {
	cur = 0;
}
void maintain(int p) {
	int lc = t[p].lc, rc = t[p].rc;
	t[p].minv = t[p].tag;
	if (t[p].r > t[p].l) {
		t[p].minv = min({ t[lc].minv, t[rc].minv, t[p].tag });
	}
}
int build(int L, int R) { //只要计算mid的方式是(L + R) >> 1而不是(L + R) / 2，就可以建立负坐标线段树。
	int p = ++cur;
	t[p].l = L;
	t[p].r = R;
	t[p].tag = inf; //重置结点标记
	if (L < R) {
		int mid = (L + R) >> 1;
		t[p].lc = build(L, mid);
		t[p].rc = build(mid + 1, R);
	}
	maintain(p);
	return p;
}
int update(int i, int L, int R, int v) { //区间取min
	int p = ++cur; t[p] = t[i];
	if (L <= t[p].l && R >= t[p].r) {
		t[p].tag = min(t[p].tag, v);
	}
	else {
		int mid = (t[p].l + t[p].r) >> 1;
		if (L <= mid)
			t[p].lc = update(t[p].lc, L, R, v);
		if (R > mid)
			t[p].rc = update(t[p].rc, L, R, v);
	}
	maintain(p);
	return p;
}
void query(int p, int L, int R) { //调用之前设置mn = inf，查询区间最小值
	mn = min(mn, t[p].tag);
	if (L <= t[p].l && R >= t[p].r) {
		mn = min(mn, t[p].minv);
	}
	else {
		int mid = (t[p].l + t[p].r) >> 1;
		if (L <= mid) 
			query(t[p].lc, L, R);
		if (R > mid) 
			query(t[p].rc, L, R);
	}
}
int main() {
	init();
	int root[10], n = 10;
	root[0] = build(1, n);
	root[1] = update(root[0], 1, 7, 10);
	root[2] = update(root[1], 5, 8, 0);
	mn = inf; query(root[2], 7, 7);
	printf("%d\n", mn);
	return 0;
}

﻿#include <cstdio>
#include <cstdlib>
#include <random>
#include <algorithm>
#include <iostream>
using namespace std;
const int maxn = 1100;
const int inf = 1 << 30;
int A[2000][2000];
int cur = 0, tot, mn, mx;
struct area {
	int x1, x2, y1, y2;
	int a, b, c, d;
	int sum, min, max, set, add; //set必须是非负数
}t[maxn * maxn * 4];
void init() {
	cur = 0;
	t[0].min = inf;
	t[0].max = -inf;
	t[0].sum = 0;
}
void maintain(int p) { //maintain函数用来维护结点信息，应当保证多次对一个结点调用maintain结果不变
	if (p == 0) return;
	int a = t[p].a, b = t[p].b, c = t[p].c, d = t[p].d;
	t[p].sum = t[p].min = t[p].max = 0;
	if (t[p].x1 != t[p].x2 || t[p].y1 != t[p].y2) {
		t[p].sum = t[a].sum + t[b].sum + t[c].sum + t[d].sum;
		t[p].min = min({ t[a].min, t[b].min, t[c].min, t[d].min });
		t[p].max = max({ t[a].max, t[b].max, t[c].max, t[d].max });
	}
	if (t[p].set >= 0) {
		t[p].min = t[p].max = t[p].set;
		t[p].sum = t[p].set * (t[p].x2 - t[p].x1 + 1) * (t[p].y2 - t[p].y1 + 1);
	}
	if (t[p].add) {
		t[p].min += t[p].add;
		t[p].max += t[p].add;
		t[p].sum += t[p].add * (t[p].x2 - t[p].x1 + 1) * (t[p].y2 - t[p].y1 + 1);
	}
}
void pushdown(int p) { //pushdown将标记传递给子结点，不影响当前结点的信息。
	int a = t[p].a, b = t[p].b, c = t[p].c, d = t[p].d;
	if (t[p].set >= 0) {
		t[a].set = t[b].set = t[c].set = t[d].set = t[p].set;
		t[a].add = t[b].add = t[c].add = t[d].add = 0;
		t[p].set = -1;
	}
	if (t[p].add) {
		t[a].add += t[p].add;
		t[b].add += t[p].add;
		t[c].add += t[p].add;
		t[d].add += t[p].add;
		t[p].add = 0;
	}
}
int build(int x1, int x2, int y1, int y2) {
	int p = ++cur;
	t[p].x1 = x1;
	t[p].x2 = x2;
	t[p].y1 = y1;
	t[p].y2 = y2;
	t[p].a = t[p].b = t[p].c = t[p].d = 0;
	t[p].add = 0; t[p].set = -1; //清空结点标记
	if (x1 == x2 && y1 == y2) {
		t[p].add = A[x1][y1];
	}
	else {
		int xm = (x1 + x2) >> 1;
		int ym = (y1 + y2) >> 1;
		t[p].a = build(x1, xm, y1, ym);
		if (ym < y2)
			t[p].b = build(x1, xm, ym + 1, y2);
		if (xm < x2)
			t[p].c = build(xm + 1, x2, y1, ym);
		if (xm < x2 && ym < y2)
			t[p].d = build(xm + 1, x2, ym + 1, y2);
	}
	maintain(p);
	return p;
}
void update(int p, int U, int D, int L, int R, int op, int v) { //[U, D]对应行号区间，[L, R]对应列号区间。
	if (U <= t[p].x1 && D >= t[p].x2 && L <= t[p].y1 && R >= t[p].y2) {
		if (op == 0) t[p].add += v;
		else {
			t[p].set = v;
			t[p].add = 0;
		}
	}
	else {
		pushdown(p);
		int xm = (t[p].x1 + t[p].x2) >> 1;
		int ym = (t[p].y1 + t[p].y2) >> 1;
		if (U <= xm && L <= ym)
			update(t[p].a, U, D, L, R, op, v);
		else
			maintain(t[p].a);
		if (U <= xm && ym < R && ym < t[p].y2)
			update(t[p].b, U, D, L, R, op, v);
		else
			maintain(t[p].b);
		if (xm < D && L <= ym && xm < t[p].x2)
			update(t[p].c, U, D, L, R, op, v);
		else
			maintain(t[p].c);
		if (xm < D && ym < R && xm < t[p].x2 && ym < t[p].y2)
			update(t[p].d, U, D, L, R, op, v);
		else
			maintain(t[p].d);
	}
	maintain(p);
}
void query(int p, int U, int D, int L, int R) { //调用之前要设置：mn = inf; mx = -inf; tot = 0;	
	if (U <= t[p].x1 && D >= t[p].x2 && L <= t[p].y1 && R >= t[p].y2) {
		tot += t[p].sum;
		mn = min(mn, t[p].min);
		mx = max(mx, t[p].max);
	}
	else {
		pushdown(p);
		maintain(t[p].a);
		maintain(t[p].b);
		maintain(t[p].c);
		maintain(t[p].d);
		int xm = (t[p].x1 + t[p].x2) >> 1;
		int ym = (t[p].y1 + t[p].y2) >> 1;
		if (U <= xm && L <= ym)
			query(t[p].a, U, D, L, R);
		if (U <= xm && ym < R && ym < t[p].y2)
			query(t[p].b, U, D, L, R);
		if (xm < D && L <= ym && xm < t[p].x2)
			query(t[p].c, U, D, L, R);
		if (xm < D && ym < R && xm < t[p].x2 && ym < t[p].y2)
			query(t[p].d, U, D, L, R);
	}
}
int main() {
#define ran engine(e)
	int n = 500, m = 500, q = 10000;
	default_random_engine e;
	e.seed(123);
	uniform_int_distribution<unsigned> engine(1, n);
	for (int i = 1; i <= n; ++i)
		for (int j = 1; j <= m; ++j)
			A[i][j] = ran;
	init();
	int root = build(1, n, 1, m);
	while (q--) {
		int a = ran, b = ran, c = ran, d = ran;
		int x1 = min(a, b), x2 = max(a, b), y1 = min(c, d), y2 = max(c, d);
		int tp = rand() % 3, v = ran;
		if (tp == 0) {
			for (int i = x1; i <= x2; ++i)
				for (int j = y1; j <= y2; ++j)
					A[i][j] += v;
			update(root, x1, x2, y1, y2, 0, v);
		}
		else if (tp == 1) {
			for (int i = x1; i <= x2; ++i)
				for (int j = y1; j <= y2; ++j)
					A[i][j] = v;
			update(root, x1, x2, y1, y2, 1, v);
		}
		else {
			mn = inf; mx = -inf; tot = 0;
			int MN = inf, MX = -inf, TOT = 0;
			for (int i = x1; i <= x2; ++i)
				for (int j = y1; j <= y2; ++j)
					MN = min(MN, A[i][j]), MX = max(MX, A[i][j]), TOT += A[i][j];
			query(root, x1, x2, y1, y2);
			if (MN != mn)
				printf("mn: %d %d\n", MN, mn);
			if (mx != MX)
				printf("mx: %d %d\n", MX, mx);
			if (tot != TOT)
				printf("sum: %d %d\n", TOT, tot);
		}
	}
	return 0;
}

﻿#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <iostream>
#include <algorithm>
#include <random>
#include <vector>
#include <ctime>
#include <iterator>
using namespace std;
const int inf = 1 << 30;
static const int maxn = 210000; //maxn应当大于所有集合大小的总和
struct node {		//该算法实现的整数集合为可重集合（multiset）
	int l, r, v;	//左节点编号 右节点编号 值
} T[maxn * 25];
int len, sz, info[maxn]; //len是值域线段树的长度
int ranking(int v) {
	//如果不需要数据离散化直接return v即可，同时还要将所有的info[v]改为v，此时线段树的值域为[1, len]。
	return lower_bound(info + 1, info + len + 1, v) - info;
}
void ins(int& i, int l, int r, int p) { //在区间[l, r]中插入p 
	if (!i) {
		i = ++sz;
		T[i].v = T[i].l = T[i].r = 0;
	}
	int m = (l + r) / 2;
	T[i].v++; //递增当前区间内值的个数 
	if (l == r) return;
	if (p <= m) ins(T[i].l, l, m, p);
	else ins(T[i].r, m + 1, r, p);
}
void insert(int& x, int v) { //向集合x中添加数值v
	ins(x, 1, len, ranking(v));
}
void init(int* A, int length) { //输入数组A的下标从1开始，length表示A的长度
	sz = 0;						//A记录集合中所有可能出现的整数
	copy(A + 1, A + length + 1, info + 1);
	sort(info + 1, info + length + 1); //如果没有离散化需要对len进行赋值来指明线段树的值域。
	len = unique(info + 1, info + length + 1) - info - 1; //对info数组进行排序去重
}
int kth(int x, int k) { //查找集合x中的第k大元素
	int l = 1, r = len;
	while (l < r) {
		int m = (l + r) / 2, t = T[T[x].l].v;
		if (k <= t)
			x = T[x].l, r = m;
		else
			x = T[x].r, l = m + 1, k -= t;
	}
	if (k > T[x].v) //如果k大于集合x的大小，则返回inf
		return inf;
	return info[r];
}
int ask(int x, int v) { //返回集合x中比v小的数的个数
	int l = 1, r = len, k = 0;
	int p = ranking(v) - 1;
	if (p <= 0) return 0;
	while (l < r) {
		int m = (l + r) / 2, t = T[T[x].l].v;
		if (p <= m)
			x = T[x].l, r = m;
		else
			x = T[x].r, l = m + 1, k += t;
	}
	k += T[x].v;
	return k;
}
int pre(int x, int v) { //在集合x中查询v的前驱，找不到返回-inf
	int k = ask(x, v);
	if (k == 0) return -inf;
	return kth(x, k);
}
int next(int x, int v) { //在集合x中查询v的后继，找不到返回inf
	int k = ask(x, v + 1) + 1;
	return kth(x, k);
}
int count(int x, int v) { //返回集合x中数值v的个数
	int l = 1, r = len;
	int p = ranking(v);
	if (p > len || info[p] != v)
		return 0;
	while (l < r && T[x].v> 0) {
		int m = (l + r) / 2;
		if (p <= m)
			x = T[x].l, r = m;
		else
			x = T[x].r, l = m + 1;
	}
	return T[x].v;
}
bool find(int x, int v) { //返回集合x中是否存在v
	return count(x, v) >= 1;
}
int maximum(int x) { //返回集合x中的最大值
	int l = 1, r = len;
	if (T[x].v == 0) //如果集合为空则返回-inf
		return -inf;
	while (l < r) {
		int m = (l + r) / 2, t = T[T[x].r].v;
		if (t == 0)
			x = T[x].l, r = m;
		else
			x = T[x].r, l = m + 1;
	}
	return info[r];
}
int minimum(int x) { //返回集合x中的最小值
	int l = 1, r = len;
	if (T[x].v == 0) //如果集合为空则返回inf
		return inf;
	while (l < r) {
		int m = (l + r) / 2, t = T[T[x].l].v;
		if (t > 0)
			x = T[x].l, r = m;
		else
			x = T[x].r, l = m + 1;
	}
	return info[r];
}
int merge(int x, int y, int l = 1, int r = len) {	//将集合x与集合y合并成一个新的集合后返回
	if (!x) return y;								//合并之后x、y均会失效
	if (!y) return x;
	if (l == r) {
		T[x].v += T[y].v;
	}
	else {
		int m = (l + r) / 2;
		T[x].l = merge(T[x].l, T[y].l, l, m);
		T[x].r = merge(T[x].r, T[y].r, m + 1, r);
		T[x].v = T[T[x].l].v + T[T[x].r].v;
	}
	return x;
}
int diff(int x, int y, int l = 1, int r = len) {	//返回集合x与集合y的差集（x - y）,执行之后x、y均会失效						
	if (l == r) {									//时间复杂度size(y)log(len)
		T[x].v = max(0, T[x].v - T[y].v);
	}
	else {
		int m = (l + r) / 2;
		if (T[y].l)
			T[x].l = diff(T[x].l, T[y].l, l, m);
		if (T[y].r)
			T[x].r = diff(T[x].r, T[y].r, m + 1, r);
		T[x].v = T[T[x].l].v + T[T[x].r].v;
	}
	return x;
}
int intersect(int x, int y, int l = 1, int r = len) {	//返回集合x与集合y的交集，执行之后x、y均会失效						
	if (l == r) {									//时间复杂度min{size(x),size(y)} * log(len)
		T[x].v = min(T[x].v, T[y].v);
	}
	else {
		int m = (l + r) / 2;
		T[x].l = (!T[x].l || !T[y].l ? 0 : intersect(T[x].l, T[y].l, l, m));
		T[x].r = (!T[x].r || !T[y].r ? 0 : intersect(T[x].r, T[y].r, m + 1, r));
		T[x].v = T[T[x].l].v + T[T[x].r].v;
	}
	return T[x].v == 0 ? 0 : x;
}
int symmetric(int x, int y, int l = 1, int r = len) {	//返回集合x与集合y的对称差分，执行之后x、y均会失效						
	if (!x) return y;									//时间复杂度min{size(x),size(y)} * log(len)
	if (!y) return x;
	if (l == r) {
		T[x].v = abs(T[x].v - T[y].v);
	}
	else {
		int m = (l + r) / 2;
		T[x].l = symmetric(T[x].l, T[y].l, l, m);
		T[x].r = symmetric(T[x].r, T[y].r, m + 1, r);
		T[x].v = T[T[x].l].v + T[T[x].r].v;
	}
	return x;
}
void left(vector<int>& X, vector<int>& Y) {
	for (auto& i : X)
		i = T[i].l;
	for (auto& i : Y)
		i = T[i].l;
}
void right(vector<int>& X, vector<int>& Y) {
	for (auto& i : X)
		i = T[i].r;
	for (auto& i : Y)
		i = T[i].r;
}
int left_value(vector<int>& X, vector<int>& Y) {
	int tot = 0;
	for (auto i : X)
		tot += T[T[i].l].v;
	for (auto i : Y)
		tot -= T[T[i].l].v;
	return tot;
}
int right_value(vector<int>& X, vector<int>& Y) {
	int tot = 0;
	for (auto i : X)
		tot += T[T[i].r].v;
	for (auto i : Y)
		tot -= T[T[i].r].v;
	return tot;
}
int value(vector<int>& X, vector<int>& Y) {
	int tot = 0;
	for (auto i : X)
		tot += T[i].v;
	for (auto i : Y)
		tot -= T[i].v;
	return tot;
}
int kth(vector<int> X, vector<int> Y, int k) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合的第k大
	int l = 1, r = len;							//必须保证Y的并集 是 X的并集 的子集
	while (l < r) {
		int m = (l + r) / 2, t = left_value(X, Y);
		if (k <= t)
			left(X, Y), r = m;
		else
			right(X, Y), l = m + 1, k -= t;
	}
	if (k > value(X, Y))
		return inf;
	return info[r];
}
int ask(vector<int> X, vector<int> Y, int v) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合中比v小的数的个数
	int l = 1, r = len, k = 0;					//必须保证Y的并集 是 X的并集 的子集
	int p = ranking(v) - 1;
	if (p <= 0) return 0;
	while (l < r) {
		int m = (l + r) / 2;
		if (p <= m)
			left(X, Y), r = m;
		else {
			k += left_value(X, Y);
			right(X, Y);
			l = m + 1;
		}
	}
	k += value(X, Y);
	return k;
}
int pre(vector<int> X, vector<int> Y, int v) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合中v的前驱
	int k = ask(X, Y, v);						//必须保证Y的并集 是 X的并集 的子集
	if (k == 0) return -inf; //找不到返回-inf
	return kth(X, Y, k);
}
int next(vector<int> X, vector<int> Y, int v) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合中v的后继
	int k = ask(X, Y, v + 1) + 1;				//必须保证Y的并集 是 X的并集 的子集
	return kth(X, Y, k); //找不到返回inf
}
int count(vector<int> X, vector<int> Y, int v) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合中v的个数
	int l = 1, r = len;								//必须保证Y的并集 是 X的并集 的子集
	int p = ranking(v);
	if (p > len || info[p] != v)
		return 0;
	while (l < r) {
		int m = (l + r) / 2;
		if (p <= m)
			left(X, Y), r = m;
		else
			right(X, Y), l = m + 1;
	}
	return value(X, Y);
}
int maximum(vector<int> X, vector<int> Y) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合中的最大值
	int l = 1, r = len;						//必须保证Y的并集 是 X的并集 的子集
	if (value(X, Y) == 0) //如果集合为空则返回-inf
		return -inf;
	while (l < r) {
		int m = (l + r) / 2, t = right_value(X, Y);
		if (t == 0)
			left(X, Y), r = m;
		else
			right(X, Y), l = m + 1;
	}
	return info[r];
}
int minimum(vector<int> X, vector<int> Y) {	//计算X中集合的并集 减去 Y中集合的并集 所得集合中的最小值
	int l = 1, r = len;						//必须保证Y的并集 是 X的并集 的子集
	if (value(X, Y) == 0) //如果集合为空则返回inf
		return inf;
	while (l < r) {
		int m = (l + r) / 2, t = left_value(X, Y);
		if (t > 0)
			left(X, Y), r = m;
		else
			right(X, Y), l = m + 1;
	}
	return info[r];
}

