		}
		else if (op == 1) {
			for (int i = L; i <= R; ++i)
				A[i] = v;
			update(root, L, R, op, v);
		}
		else if (op == 2) {
			mn = inf; mx = -inf; tot = 0;
			query(root, L, R);
