    scanf("%d", &n);
    init(n);
    for (int i = 1; i < n; ++i) {
        int x, y, w;
        scanf("%d %d %d", &x, &y, &w);
        G[x].emplace_back(y, w);
        G[y].emplace_back(x, w);
    }

    DFS1(1, 0, 1);
    DFS2(1, 1);
    solve(1, n);

    return 0;
}

