int dfs1(int u, int fa, int cnt) { //�����uΪ�������������� 
	int tot = 1, num = 0;
	for (int i = head[u]; i; i = nxt[i]) {
		int v = to[i];
		if (v != fa && !vis[v]) {
			int result = dfs1(v, u, cnt);
			tot += result;
			num = max(num, result);
		}
	}
	num = max(num, cnt - tot);
	if (num < sz) {
		sz = num;
		pos = u;
	}
	return tot;
}
void dfs2(int u, int fa, int host) {
	tree.insert(root[host], dist(u, host), value[u]);
	for (int i = head[u]; i; i = nxt[i]) {
		int v = to[i];
		if (v != fa && !vis[v]) {
			dfs2(v, u, host);
		}
	}
}
void dfs3(int u, int fa, int host) {
	tree.insert(root2[host], dist(u, pa[host]), value[u]);
	for (int i = head[u]; i; i = nxt[i]) {
		int v = to[i];
		if (v != fa && !vis[v]) {
			dfs3(v, u, host);
		}
	}
}
void build(int u, int cnt, int pre = 0) { //�ݹ鴦������u��cntΪ����u�еĽ������
	sz = inf;
	dfs1(u, -1, cnt); //�����uΪ��������������root����Ϊ�µĸ����
	int root = pos;
	vis[root] = 1; //���root��㲻���ٱ�����
	pa[root] = pre;
	dfs2(root, -1, root);
	if (pre) dfs3(root, -1, root);
	for (int i = head[root]; i; i = nxt[i]) {
		int v = to[i];
		if (!vis[v]) {
			build(v, dfs0(v, -1), root);
		}
	}
}
long long query(int x, int k) {
	long long res = tree.sum(root[x], k);
	for (int i = x; pa[i]; i = pa[i]) {
		int d = dist(x, pa[i]);
		if (k - d >= 0) {
			res += tree.sum(root[pa[i]], k - d);
			res -= tree.sum(root2[i], k - d);
		}
	}
	return res;
}
void update(int x, int delta) {
	tree.insert(root[x], 0, delta);
	for (int i = x; pa[i]; i = pa[i]) {
		int d = dist(pa[i], x);
		tree.insert(root[pa[i]], d, delta);
		tree.insert(root2[i], d, delta);
	}
}
int main() {
//	freopen("in.txt", "r", stdin);
	int n, m;
	scanf("%d %d", &n, &m);
	init();
	tree.init(0, 110000);
	for (int i = 1; i <= n; ++i)
		root[i] = tree.newnode();
	for (int i = 1; i <= n; ++i)
		root2[i] = tree.newnode();
	for (int i = 1; i <= n; ++i)
		scanf("%d", &value[i]);
	for (int i = 1; i < n; ++i) {
		int u, v;
		scanf("%d %d", &u, &v);
		insert(u, v);
		insert(v, u);
	}
	DFS1(1, 0, 1);
	DFS2(1, 1);
	build(1, n);
	long long ans = 0;
	while (m--) {
		long long tp, x, y;
		scanf("%lld %lld %lld", &tp, &x, &y);
		x ^= ans; y ^= ans;
		if (tp == 0) {
			ans = query(x, y);
			printf("%lld\n", ans);
		}
		else {
			int delta = y - value[x];
			value[x] = y;
			update(x, delta);
		}
	}
	return 0;
}

﻿/*
seq下标从1开始，表示欧拉序列。欧拉序列记录的是点的标号，一段欧拉序列中若一个点出现了两次则不予处理。
树上的一条路径一定对应一段连续的欧拉序列（可能还要并上一个额外的点）。
*/
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
using namespace std;
const int maxn = 210000;
const int maxlog = 25;
int head[maxn], nxt[maxn], to[maxn], seq[maxn], depth[maxn], anc[maxn][maxlog], first[maxn], last[maxn], cur, sz;
struct item { //下标区间[L, R]的欧拉序列，若lca != 0则还要将lca考虑进来
	int L, R, lca;
	item(){}
	item(int L, int R, int lca) : L(L), R(R), lca(lca){}
};
void init() {
	cur = sz = 0;
	memset(head, 0, sizeof(head));
	memset(depth, 0, sizeof(depth));
	memset(anc, 0, sizeof(anc));
}
void add_edge(int x, int y) { //对于树中的每条边要调用两次add_edge
	to[++cur] = y;
	nxt[cur] = head[x];
	head[x] = cur;
}
void dfs(int x, int fa) { //dfs(1, 0)
	seq[++sz] = x;
	first[x] = sz;
	for (int i = head[x]; i; i = nxt[i]) if (to[i] != fa) {
		int y = to[i];
		depth[y] = depth[x] + 1;
		anc[y][0] = x;
		for (int i = 1; (1 << i) <= depth[y]; ++i) 
			anc[y][i] = anc[anc[y][i - 1]][i - 1];
		dfs(y, x);
	}
	seq[++sz] = x;
	last[x] = sz;
}
int getlca(int x, int y) {
	if (depth[x] < depth[y])
		swap(x, y);
	for (int i = maxlog - 1; i >= 0; --i)
		if (depth[x] - (1 << i) >= depth[y])
			x = anc[x][i];
	if (x == y)
		return x;
	for (int i = maxlog - 1; i >= 0; --i)
		if (anc[x][i] != anc[y][i]) 
			x = anc[x][i], y = anc[y][i];
	return anc[x][0];
}
item path(int x, int y) { //返回树上x到y的路径对应的欧拉序列
	if (first[x] > first[y])
		swap(x, y);
	int lca = getlca(x, y);
	if (lca == x)
		return item(first[x], first[y], 0);
	else
		return item(last[x], first[y], lca);
}
