	return 0;
}

﻿#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <vector>
#define dfs1(x, fa, d)
#define dfs2(x, fa, d)
using namespace std;
const int maxn = 110000;
vector<pair<int, int>> G[maxn]; //to, weight
int vis[maxn], siz[maxn], f[maxn], pos, sum;
void init(int n) {
	for (int i = 0; i <= n; ++i) {
		vis[i] = false;
		G[i].clear();
	}
}
void getroot(int x, int fa) {
    f[x] = 0; siz[x] = 1;
    for (auto[y, w] : G[x]) if (y != fa && !vis[y]) {
        getroot(y, x); 
        f[x] = max(f[x], siz[y]);
        siz[x] += siz[y];
    }
    f[x] = max(f[x], sum - siz[x]);
    if (f[x] < f[pos])
        pos = x;
}
void calc(int x) { //统计经过结点x的所有答案
    for (auto [y, w] : G[x]) if (!vis[y]) {
        //注意在dfs中枚举子结点y的时候要判两个条件：y != fa && !vis[y]
        dfs1(y, x, w); //计算当前子树与之前子树以及 结点x 连接构成的路径。
        dfs2(y, x, w); //维护处理过的子树的信息
    }
    //维护信息的时候有两种方案：
    //1. 在每次calc调用的时候新建一个数据结构维护。
    //2. 维护一个全局的数据结构，此时在calc末尾应当加一个循环来撤销之前的所有操作。
}
void solve(int x, int cnt) { //cnt为子树x中的结点总数
    pos = maxn - 1; f[pos] = sum = cnt;
    getroot(x, -1);
    int root = pos; //因为pos是全局变量，递归的时候值会改变，所以此处存为局部变量。
    vis[root] = 1;
    calc(root);
    for (auto [y, w] : G[root]) if (!vis[y])
        solve(y, siz[y] < siz[root] ? siz[y] : cnt - siz[root]);
}
int main() {
    int n;
    scanf("%d", &n);
    init(n);
    for (int i = 1; i < n; ++i) {
        int x, y, w;
        scanf("%d %d %d", &x, &y, &w);
        G[x].emplace_back(y, w);
        G[y].emplace_back(x, w);
    }
    solve(1, n);
	return 0;
}

﻿/*
ins函数会在每个结点i第一次入栈的时候，将E[i]清空。这样在最坏情况下空间复杂度可达O(nlogn)，
可以改成在每次询问后用一个DFS清空E，这样也E就不会占用额外内存了。
*/
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
const int maxn = 1110000;
int dep[maxn], sz[maxn], pa[maxn], son[maxn], top[maxn], stk[maxn], dfn[maxn], clk, tp;
vector<int> G[maxn], E[maxn];
void dfs1(int u, int fa, int d) {
	dfn[u] = ++clk;
	dep[u] = d;
	sz[u] = 1;
	son[u] = 0;
	pa[u] = fa;
	for (auto v : G[u]) if (v != fa) {
		dfs1(v, u, d + 1);
		sz[u] += sz[v];
		if (sz[son[u]] < sz[v])
			son[u] = v;
	}
}
void dfs2(int u, int tp) {
	top[u] = tp;
	if (son[u])
		dfs2(son[u], tp);
	for (auto v : G[u]) if (v != pa[u] && v != son[u])
		dfs2(v, v);
}
int lca(int x, int y) {
	while (top[x] != top[y]) {
		if (dep[top[x]] < dep[top[y]])
			swap(x, y);
		x = pa[top[x]];
	}
	return dep[x] < dep[y] ? x : y;
}
int dist(int x, int y) {
	return dep[x] + dep[y] - 2 * dep[lca(x, y)];
}
void init(int root) {
	clk = 0; stk[0] = -1;
	dfs1(root, 0, 1);
	dfs2(root, root);
}
void ins(int x) {
	if (tp > 0) {
		int fa = lca(stk[tp], x);
		if (fa != stk[tp]) {
			while (tp > 1 && dep[fa] < dep[stk[tp - 1]]) {
				E[stk[tp - 1]].push_back(stk[tp]);
				--tp;
			}
			int last = stk[tp--];
			if (fa != stk[tp]) {
				E[fa].clear();
				stk[++tp] = fa;
			}
			E[fa].push_back(last);
		}
	}
	E[x].clear();
	stk[++tp] = x;
}
int build(vector<int> nodes) { //对集合nodes中的结点建立虚树，并返回根结点。
	sort(nodes.begin(), nodes.end(), [](int x, int y) {
		return dfn[x] < dfn[y];
	});
	for (auto i : nodes)
		ins(i);
	while (--tp) 
		E[stk[tp]].push_back(stk[tp + 1]);
	return stk[1];
}

int main() {
	return 0;
}

﻿/*
该算法用来求解有根树中结点v的子树中与v距离不超过d的所有结点的权值和（也可以求最值等），
时间复杂度O(d)，若用倍增可以优化到O(logd)。
调用init函数之前应当输入n（结点标号从1开始），以及用add_edge建图。
*/
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <vector>
#include <queue>
using namespace std;
const int maxn = 1010000;
int n, q, w[maxn], head[maxn], nxt[maxn * 2], to[maxn * 2], id[maxn], l[maxn], r[maxn];
int father[maxn], depth[maxn], seq[maxn], cur = 0;
long long sum[maxn];
void add_edge(int u, int v) {
	to[++cur] = v;
	nxt[cur] = head[u];
	head[u] = cur;
}
void init() {
	int sz = 0;
	queue<int> Q;
	father[1] = depth[1] = seq[n + 1] = 0;
	Q.push(1);
	while (!Q.empty()) {
		int x = Q.front(); Q.pop();
		seq[++sz] = x;
		id[x] = sz;
		l[x] = r[x] = 0;
		for (int i = head[x]; i; i = nxt[i]) if (to[i] != father[x]) {
			int y = to[i];
			l[x] = (l[x] ? l[x] : y);
			r[x] = y;
			father[y] = x;
			depth[y] = depth[x] + 1;
			Q.push(y);
		}
	}
	for (int j = 1; j <= n; ++j)
		sum[j] = sum[j - 1] + w[seq[j]];
	for (int j = 1; j <= n; ++j) if (!r[seq[j]])
		r[seq[j]] = r[seq[j - 1]];
	for (int j = n; j >= 1; --j) if (!l[seq[j]])
		l[seq[j]] = l[seq[j + 1]];
}
long long travel(int x, int d) { //求出以x为根的子树中与x距离不超过d的所有结点的权值和（可改为求最值或种类数）
	if (d < 0) return 0;		 //时间复杂度O(d)，可以改成倍增使得时间复杂度变为O(logd)
	long long ret = 0;
	int L = x, R = x;
	for (int i = 0; i <= d; ++i) {
		int left = id[L], right = id[R];
		if (L == 0 || R == 0 || left > right) break;
		long long s = sum[right] - sum[left - 1];
		ret += s;
		L = l[L];
		R = r[R];
	}
	return ret;
}

int main() {
	//freopen("in.txt", "r", stdin);
	scanf("%d", &n);
	for (int i = 1; i <= n; ++i)
		scanf("%d", &w[i]);
	for (int i = 0; i < n - 1; ++i) {
		int u, v;
		scanf("%d %d", &u, &v);
		add_edge(u, v);
		add_edge(v, u);
	}
	init();
	scanf("%d", &q);
	while (q--) { //每次询问求出树中与v距离不超过k的所有点的权值和，复杂度O(k^2)
		int v, k;
		scanf("%d %d", &v, &k);
		long long ans = travel(v, k);
		int last = v;
		for (int u = father[v], t = k - 1; u != 0 && t >= 0; u = father[u], --t) {
			ans += travel(u, t) - travel(last, t - 1);
			last = u;
		}
		printf("%lld\n", ans);
	}
	return 0;
}

﻿#include <cstdio>
