using namespace std;
const int maxn = 100000 + 10;
const int inf = 1 << 30;
struct edge{
	int from, to, cap, flow;
	edge(int u, int v, int c, int f) : from(u), to(v), cap(c), flow(f) {}
};
struct Dinic {
	int n, m, s, t;
	vector<edge> edges;    // 边数的两倍
	vector<int> G[maxn];   // 邻接表，G[i][j]表示结点i的第j条边在e数组中的序号
	bool vis[maxn];        // BFS使用
	int d[maxn];           // 从起点到i的距离
	int cur[maxn];         // 当前弧指针
	void init(int n) {
		this->n = n;
		for (int i = 0; i < n; i++)
			G[i].clear();
		edges.clear();
	}
	void clear() {
		for (int i = 0; i < edges.size(); i++)
			edges[i].flow = 0;
	}
	void reduce() {
		for (int i = 0; i < edges.size(); i++)
			edges[i].cap -= edges[i].flow;
	}
	void addedge(int from, int to, int cap) {
		edges.push_back(edge(from, to, cap, 0));
		edges.push_back(edge(to, from, 0, 0));
		m = edges.size();
		G[from].push_back(m - 2);
		G[to].push_back(m - 1);
	}
	bool BFS() {
		memset(vis, 0, sizeof(vis));
		queue<int> Q;
		Q.push(s);
		vis[s] = 1;
		d[s] = 0;
		while (!Q.empty()) {
			int x = Q.front(); Q.pop();
			for (int i = 0; i < G[x].size(); i++) {
				edge& e = edges[G[x][i]];
				if (!vis[e.to] && e.cap > e.flow) {
					vis[e.to] = 1;
					d[e.to] = d[x] + 1;
					Q.push(e.to);
				}
			}
		}
		return vis[t];
	}
	int DFS(int x, int a) {
		if (x == t || a == 0) return a;
		int flow = 0, f;
		for (int& i = cur[x]; i < G[x].size(); i++) {
			edge& e = edges[G[x][i]];
			if (d[x] + 1 == d[e.to] && (f = DFS(e.to, min(a, e.cap - e.flow))) > 0) {
				e.flow += f;
				edges[G[x][i] ^ 1].flow -= f;
				flow += f;
				a -= f;
				if (a == 0) break;
			}
		}
		return flow;
	}
	int Maxflow(int s, int t) {
		this->s = s; this->t = t;
		int flow = 0;
		while (BFS()) {
			memset(cur, 0, sizeof(cur));
			flow += DFS(s, inf);
		}
		return flow;
	}
	vector<int> Mincut() { // call this after maxflow
		vector<int> ans;
		for (int i = 0; i < edges.size(); i++) {
			edge& e = edges[i];
			if (vis[e.from] && !vis[e.to] && e.cap > 0)
				ans.push_back(i);
		}
		return ans;
	}
}dinic;
int main()
{
	freopen("D:\\in.txt", "r", stdin);
	int n, m;
	scanf("%d %d", &n, &m);
	dinic.init(n + 5);
	while (m--) {
		int s, t, u;
		scanf("%d %d %d", &s, &t, &u);
		dinic.addedge(s, t, u);
	}
	auto start = clock();
	printf("%d\n", dinic.Maxflow(1, n));
	double tot = static_cast<double>(clock() - start) / CLOCKS_PER_SEC;
	printf("Dinic: %f\n", tot);
	return 0;
}

﻿#include <cstdio>
#include <cstring>
#include <algorithm>
#include <queue>
#include <ctime>
using namespace std;
const int maxn = 2e5 + 5, maxedges = 4e6 + 5, inf = 0x3f3f3f3f;
int n, m, s, t, tot;
int v[maxedges * 2], w[maxedges * 2], first[maxn], nxt[maxedges * 2];
int h[maxn], e[maxn], gap[maxn * 2], inq[maxn];//节点高度是可以到达2n-1的
struct cmp{
	inline bool operator()(int a, int b) const {
		return h[a] < h[b];//因为在优先队列中的节点高度不会改变，所以可以直接比较
	}
};
queue<int> Q;
priority_queue<int, vector<int>, cmp> heap;
inline void add_edge(int from, int to, int flow) {
	tot += 2;
	v[tot + 1] = from; v[tot] = to; w[tot] = flow; w[tot + 1] = 0;
	nxt[tot] = first[from]; first[from] = tot;
	nxt[tot + 1] = first[to]; first[to] = tot + 1;
	return;
}
inline bool bfs() {
	memset(h + 1, 0x3f, sizeof(int) * n);
	h[t] = 0; 
	Q.push(t);
	while (!Q.empty())
	{
		int now = Q.front(); Q.pop();
		for (int go = first[now]; go; go = nxt[go])
			if (w[go ^ 1] && h[v[go]] > h[now] + 1)
				h[v[go]] = h[now] + 1, Q.push(v[go]);
	}
	return h[s] != inf;
}
inline void push(int now) {
	for (int go = first[now]; go; go = nxt[go]) {
		if (w[go] && h[v[go]] + 1 == h[now]) {
			int d = min(e[now], w[go]);
			w[go] -= d; w[go ^ 1] += d; e[now] -= d; e[v[go]] += d;
			if (v[go] != s && v[go] != t && !inq[v[go]])
				heap.push(v[go]), inq[v[go]] = 1;
			if (!e[now])//已经推送完毕可以直接退出
				break;
		}
	}
}
inline void relabel(int now) {
	h[now] = inf;
	for (int go = first[now]; go; go = nxt[go])
		if (w[go] && h[v[go]] + 1 < h[now])
			h[now] = h[v[go]] + 1;
	return;
}
inline int hlpp() {
	int now, d;
	if (!bfs()) //s和t不连通
		return 0;
	h[s] = n;
	memset(gap, 0, sizeof(int) * (n * 2));
	for (int i = 1; i <= n; i++)
		if (h[i] < inf)
			++gap[h[i]];
	for (int go = first[s]; go; go = nxt[go]) {
		if (d = w[go]) {
			w[go] -= d; w[go ^ 1] += d; e[s] -= d; e[v[go]] += d;
			if (v[go] != s && v[go] != t && !inq[v[go]])
				heap.push(v[go]), inq[v[go]] = 1;
		}
	}
	while (!heap.empty()) {
		inq[now = heap.top()] = 0; heap.pop(); push(now);
		if (e[now]) {
			if (!--gap[h[now]]) //gap优化，因为当前节点是最高的所以修改的节点一定不在优先队列中，不必担心修改对优先队列会造成影响
				for (int i = 1; i <= n; i++)
					if (i != s && i != t && h[i] > h[now] && h[i] < n + 1)
						h[i] = n + 1;
			relabel(now); ++gap[h[now]];
			heap.push(now); inq[now] = 1;
		}
	}
	return e[t];
}
int main()
{
	freopen("D:\\in.txt", "r", stdin);
	scanf("%d %d", &n, &m); s = 1; t = n;
	while (m--)
	{
		int s, t, u;
		scanf("%d %d %d", &s, &t, &u);
		add_edge(s, t, u);
	}
	auto start = clock();
	printf("%d\n", hlpp());
	double tot = static_cast<double>(clock() - start) / CLOCKS_PER_SEC;
	printf("HLPP: %f\n", tot);
	return 0;
}

﻿#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <algorithm>
#include <iostream>
#include <queue>
#include <ctime>
using namespace std;
const int maxn = 1100;
const int maxedges = 51000;
const int inf = 1 << 30;
struct edge {
	int to, flow;
	edge *next, *pair;
	edge() {}
	edge(int to, int flow, edge *next) : to(to), flow(flow), next(next) {}
	void *operator new(unsigned, void *p) { return p; }
};
struct ISAP {
	int gap[maxn], h[maxn], n, s, t;
	edge *cur[maxn], *first[maxn], edges[maxedges * 2], *ptr;
	void init(int n) {
		this->n = n;
		ptr = edges;
		memset(first, 0, sizeof(first));
		memset(gap, 0, sizeof(gap));
		memset(h, 0, sizeof(h));
		gap[0] = n;
	}
	void add_edge(int from, int to, int cap) {
		first[from] = new(ptr++)edge(to, cap, first[from]);
		first[to] = new(ptr++)edge(from, 0, first[to]);
		first[from]->pair = first[to];
		first[to]->pair = first[from];
	}
	int augment(int x, int limit) {
		if (x == t)
			return limit;
		int rest = limit;
		for (edge*& e = cur[x]; e; e = e->next) if (e->flow && h[e->to] + 1 == h[x]) {
			int d = augment(e->to, min(rest, e->flow));
			e->flow -= d, e->pair->flow += d, rest -= d;
			if (h[s] == n || !rest)
				return limit - rest;
		}
		int minh = n;
		for (edge *e = cur[x] = first[x]; e; e = e->next) if (e->flow)
			minh = min(minh, h[e->to] + 1);
		if (--gap[h[x]] == 0)
			h[s] = n;
		else
			++gap[h[x] = minh];
		return limit - rest;
	}
	int solve(int s, int t, int limit = inf) {
		this->s = s; this->t = t;
		memcpy(cur, first, sizeof(first)); // memcpy!
		int flow = 0;
		while (h[s] < n && flow < limit)
			flow += augment(s, limit - flow);
		return flow;
	}
}isap;
int main()
{
	freopen("D:\\in.txt", "r", stdin);
	int n, m;
	scanf("%d %d", &n, &m);
	isap.init(n + 5);
	while (m--)
	{
		int s, t, u;
		scanf("%d %d %d", &s, &t, &u);
		isap.add_edge(s, t, u);
	}
	auto start = clock();
	printf("%d\n", isap.solve(1, n));
	double tot = static_cast<double>(clock() - start) / CLOCKS_PER_SEC;
	printf("Isap: %f\n", tot);
	return 0;
}

﻿#include <iostream>
#include <algorithm>
#include <cstdio>
#include <cstring>
#include <vector>
#include <queue>
#include <ctime>
using namespace std;
const int maxn = 21000;
const int inf = 1 << 30;
struct edge {
	int to, cap, cost, rev;
	edge() {}
	edge(int to, int cap, int cost, int rev) : to(to), cap(cap), cost(cost), rev(rev) {}
};
struct MCMF {
	int n, h[maxn], d[maxn], pre[maxn], num[maxn];
	vector<edge> G[maxn];
	void init(int n) {
		this->n = n;
		for (int i = 0; i <= n; ++i)
			G[i].clear();
	}
	void add_edge(int from, int to, int cap, int cost) {
		G[from].push_back(edge(to, cap, cost, G[to].size()));
		G[to].push_back(edge(from, 0, -cost, G[from].size() - 1));
	}
	//flow是自己传进去的变量，就是最后的最大流，返回的是最小费用
	int solve(int s, int t, int &flow, int limit = inf) {
		int cost = 0; 
		memset(h, 0, sizeof(h));
		while (limit) {
			priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>> > Q;
			for (int i = 0; i <= n; ++i)
				d[i] = inf;
			d[s] = 0; 
			Q.emplace(0, s);
			while (!Q.empty()) {
				auto now = Q.top(); Q.pop();
				int u = now.second;
				if (d[u] < now.first) continue;
				for (int i = 0; i < G[u].size(); ++i) {
					edge &e = G[u][i];
					if (e.cap > 0 && d[e.to] > d[u] + e.cost + h[u] - h[e.to]) {
						d[e.to] = d[u] + e.cost + h[u] - h[e.to];
						pre[e.to] = u;
						num[e.to] = i;
						Q.emplace(d[e.to], e.to);
					}
				}
			}
			if (d[t] == inf) break;
			for (int i = 0; i <= n; ++i)
				h[i] += d[i];
			int a = limit;
			for (int u = t; u != s; u = pre[u])
				a = min(a, G[pre[u]][num[u]].cap);
			limit -= a; flow += a; cost += a * h[t];
			for (int u = t; u != s; u = pre[u]) {
				edge &e = G[pre[u]][num[u]];
				e.cap -= a;
				G[u][e.rev].cap += a;
			}
		}
		return cost;
	}
}mcmf;
int main()
{
	freopen("D:\\in.txt", "r", stdin);
	int n, m, k, flow = 0;
	scanf("%d %d %d", &n, &m, &k);
	mcmf.init(n + 10);
	for (int i = 1; i <= m; ++i) {
		int x, y, c, w;
		scanf("%d %d %d %d", &x, &y, &c, &w);
		mcmf.add_edge(x, y, c, w);
	}
	auto start = clock();
	printf("%d\n", mcmf.solve(1, n, flow, k));
	printf("flow: %d\n", flow);
	double tot = static_cast<double>(clock() - start) / CLOCKS_PER_SEC;
	printf("MCMF-dijkstra: %f\n", tot);
	return 0;
}

﻿#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <iostream>
#include <algorithm>
#include <vector>
#include <queue>
#include <ctime>
using namespace std;
const int maxn = 20100;
const int inf = 1 << 30;
struct edge {
	int from, to, cap, flow, cost;
	edge(int u, int v, int c, int f, int w) : from(u), to(v), cap(c), flow(f), cost(w) {}
};
struct MCMF {
	int n, m;
	vector<edge> edges;
	vector<int> G[maxn];
	int inq[maxn];
	int d[maxn];
	int p[maxn];
	int a[maxn];
	void init(int n) {
		this->n = n;
		for (int i = 0; i < n; ++i)
			G[i].clear();
		edges.clear();
	}
	void add_edge(int from, int to, int cap, int cost) {
		edges.push_back(edge(from, to, cap, 0, cost));
		edges.push_back(edge(to, from, 0, 0, -cost));
		m = edges.size();
		G[from].push_back(m - 2);
		G[to].push_back(m - 1);
	}
	bool BellmanFord(int s, int t, int &flow, int &cost, int limit) {
		for (int i = 0; i < n; ++i)
			d[i] = inf;
		memset(inq, 0, sizeof(inq));
		d[s] = 0; inq[s] = 1; p[s] = 0; a[s] = inf;
		queue<int> Q;
		Q.push(s);
		while (!Q.empty()) {
			int u = Q.front(); Q.pop();
			inq[u] = false;
			for (unsigned i = 0; i < G[u].size(); ++i) {
				edge &e = edges[G[u][i]];
				if (e.cap > e.flow && d[e.to] > d[u] + e.cost) {
					d[e.to] = d[u] + e.cost;
					p[e.to] = G[u][i];
					a[e.to] = min(a[u], e.cap - e.flow);
					if (!inq[e.to]) {
						Q.push(e.to);
						inq[e.to] = true;
					}
				}
			}
		}
		if (d[t] == inf)
			return false;
		a[t] = min(a[t], limit - flow);
		flow += a[t];
		cost += d[t] * a[t];
		for (int u = t; u != s; u = edges[p[u]].from) {
			edges[p[u]].flow += a[t];
			edges[p[u] ^ 1].flow -= a[t];
		}
		return true;
	}
	int solve(int s, int t, int limit = inf) {
		int flow = 0, cost = 0;
		while (flow < limit && BellmanFord(s, t, flow, cost, limit));
		return cost;
	}
}mcmf;
int main()
{
	freopen("D:\\in.txt", "r", stdin);
	int n, m, k;
	scanf("%d %d %d", &n, &m, &k);
	mcmf.init(n + 10);
	for (int i = 1; i <= m; ++i) {
		int x, y, c, w;
		scanf("%d %d %d %d", &x, &y, &c, &w);
		mcmf.add_edge(x, y, c, w);
	}
	auto start = clock();
	printf("%d\n", mcmf.solve(1, n, k));
	double tot = static_cast<double>(clock() - start) / CLOCKS_PER_SEC;
	printf("MCMF-spfa: %f\n", tot);
	return 0;
}

