ll mul_mod (ll x, ll y, ll n){
	ll T = floor(sqrt(n) + 0.5);
	ll t = T * T - n;
	ll a = x / T; ll b = x % T;
	ll c = y / T; ll d = y % T;
	ll e = a * c / T; ll f = a * c % T;
	ll v = ((a * d + b * c) % n + e * t) % n;
	ll g = v / T; ll h = v % T;
	ll ans = (((f + g) * t % n + b * d) % n + h * T) % n;
	while (ans < 0) ans += n;
	return ans;
