struct LCA {
    const int N;
    int n, idx;
    vector<int> id, rid, dep, fa;
    vector<vector<int>> e, st;

    LCA(int n) : N(__lg(n) + 1), n(n), idx(0), id(n, -1), rid(n), dep(n), fa(n), e(n), st(N, vector<int>(n)) {}

    void add(int u, int v) {
        e[u].push_back(v);
        e[v].push_back(u);
    }

    int getMin(int x, int y) {
        return dep[x] < dep[y] ? x : y;
    }

    void dfs(int u) {
        id[u] = idx;
        rid[idx] = u;
        idx++;

        for (int v : e[u]) {
            if (id[v] != -1) {
                continue;
            }

            dep[v] = dep[u] + 1;
            fa[v] = u;
            dfs(v);
        }
    }

    void work(int rt = 0) {
        dep[rt] = 1;
        dfs(rt);

        for (int i = 0; i < n; ++i) {
            st[0][i] = rid[i];
        }

        for (int i = 1; i < N; ++i) {
            for (int j = 0; j + (1 << i) - 1 < n; ++j) {
                st[i][j] = getMin(st[i - 1][j], st[i - 1][j + (1 << (i - 1))]);
            }
        }
    }

    int getLca(int x, int y) {
        if (x == y) {
            return x;
        }
        x = id[x], y = id[y];
        if (x > y) {
            swap(x, y);
        }
        ++x;
        int z = __lg(y - x + 1);
        return fa[getMin(st[z][x], st[z][y - (1 << z) + 1])];
    }
};

struct Dinic {
    struct Edge {
        int v;
        LL w;
        Edge(int v, LL w) : v(v), w(w) {}
    };

    int n;
    vector<Edge> edges;
    vector<int> d, cur;
    vector<vector<int>> e;
    Dinic(int n) : n(n), d(n), cur(n), e(n) {}

    void reset(int n) { 
        this->n = n;
        edges.clear();
        e.resize(n), d.resize(n), cur.resize(n);
        for (int i = 0; i < n; ++i) 
            e.clear();
    }

    void add(int u, int v, LL w) {
        e[u].push_back(edges.size());
        edges.emplace_back(v, w);
        e[v].push_back(edges.size());
        edges.emplace_back(u, 0);
    }

    bool bfs(int s, int t) {
        d.assign(n, 0);
        queue<int> q;
        d[s] = 1;
        q.push(s);
        while (q.size()) {
            int u = q.front();
            q.pop();
            for (int i : e[u]) {
                auto [v, w] = edges[i];
                if (w && !d[v]) {  // 有 w 才能保证正确性（能正确回溯）
                    d[v] = d[u] + 1;
                    q.push(v);
                    if (v == t) return 1;
                }
            }
        }
        return 0;
    }

    LL maxFlow(int s, int t) {
        LL maxflow = 0;

        auto dfs = [&](auto &&self, int u, LL flow) -> LL {
            if (u == t) {
                return flow;  // 返回至多能减多少。
            }
            LL rest = flow;
            for (int &i = cur[u]; i < (int)e[u].size(); ++i) {
                int j = e[u][i];
                auto [v, w] = edges[j];
                if (w && d[v] == d[u] + 1) {
                    LL k = self(self, v, min(rest, w));
                    if (!k) d[v] = 0;
                    rest -= k, edges[j].w -= k, edges[j ^ 1].w += k;
                    if (!rest) break;  // 这里 break 才能保证复杂度。
                }
            }
            return flow - rest;
        };

        while (bfs(s, t)) {
            cur.assign(n, 0);
            maxflow += dfs(dfs, s, numeric_limits<LL>::max());
        }

        return maxflow;
    }
};

struct DSU {
    int n;
    vector<int> fa, siz;

    DSU(int n) : n(n) {
        init(n);
    }

    void init(int n) {
        fa.resize(n);
        iota(fa.begin(), fa.end(), 0);
        siz.assign(n, 1);
    }

    int find(int x) {return (x == fa[x] ? x : fa[x] = find(fa[x]));}

    bool merge(int x, int y) {
        int fx = find(x), fy = find(y);
        if (fx == fy) return false;
        fa[fy] = fx;
        siz[fx] += siz[fy];
        return true;
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }
};

