/* 顺序容器流输出定义 */
template<class T, class = decay_t<decltype(*begin(declval<T>()))>,
class = enable_if_t<!is_same<T, string>::value>>
ostream &operator<<(ostream &os, const T &c) {
    os << "[";
    for (auto it = c.begin(); it != c.end(); ++it) {
        if (it != prev(c.end())) {
            os << *it << ", ";
        } else {
            os << *it << "]";
        }
    }
    return os;
}


